// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.28;

/**
 * @title IArbitrator
 * @notice Phase-1 FROZEN arbitration seam. An arbitrable app pays a native-value
 *         (PAS) fee to open a dispute; the arbitrator later pushes a ruling back
 *         via IArbitrable.rule and exposes a pull-based re-delivery fallback.
 * @dev Ruling convention (FROZEN): 0 = "refused to arbitrate / default", and
 *      1..numChoices are the app-defined choices. Binary disputes use numChoices = 2.
 *      The arbitrator never interprets what a choice means.
 *      Interfaces are dependency-free on purpose: no imports, enums exposed as uint8.
 */
interface IArbitrator {
    /// @notice Emitted when a dispute is created. configHash snapshots the court
    ///         config the dispute will be settled against (never live storage).
    event DisputeCreated(
        uint256 indexed disputeId,
        address indexed arbitrable,
        uint8 numChoices,
        bytes32 configHash,
        bytes extraData
    );

    /// @notice Emitted when a final ruling has been successfully delivered to the arbitrable.
    event Ruling(address indexed arbitrable, uint256 indexed disputeId, uint256 ruling);

    /// @notice Emitted when IArbitrable.rule reverted or ran out of gas; the dispute
    ///         still advances and anyone may retry via redeliverRuling.
    event RulingDeliveryFailed(address indexed arbitrable, uint256 indexed disputeId, uint256 ruling);

    /**
     * @notice Open a new dispute. msg.sender is the arbitrable app that will receive rule().
     * @param numChoices Number of app-defined choices, 2 <= numChoices <= 8 (K cap).
     * @param extraData Opaque app data, echoed in DisputeCreated. Phase-1 court ignores it.
     * @dev msg.value MUST be >= arbitrationCost(extraData); any excess is credited to the
     *      caller's withdrawable balance (pull), never pushed back.
     * @return disputeId Monotonic id, starting at 1 (0 is the null dispute).
     */
    function createDispute(uint8 numChoices, bytes calldata extraData) external payable returns (uint256 disputeId);

    /**
     * @notice Fee (native PAS wei/plancks) required by createDispute for this extraData.
     * @dev Phase-1: constant per court config; extraData is ignored but kept in the seam.
     */
    function arbitrationCost(bytes calldata extraData) external view returns (uint256 cost);

    /**
     * @notice Permissionless re-attempt of a previously failed ruling delivery.
     * @dev Reverts unless the dispute is Ruled-or-later AND the last delivery attempt failed.
     *      Idempotent: succeeds at most once per dispute.
     */
    function redeliverRuling(uint256 disputeId) external;

    /**
     * @notice Cheap status probe for apps and keepers.
     * @return state DisputeState as uint8 (see core Types: 0 None .. 7 Settled).
     * @return ruling Final ruling; only meaningful once state >= 5 (Tallied).
     * @return delivered True iff IArbitrable.rule has been successfully executed.
     */
    function disputeStatus(uint256 disputeId) external view returns (uint8 state, uint256 ruling, bool delivered);
}

// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.28;

/**
 * @title IArbitrable
 * @notice Phase-1 FROZEN callback seam implemented by any app that consumes rulings.
 * @dev The arbitrator calls rule() exactly once per dispute inside try/catch. If rule()
 *      reverts, the arbitrator emits RulingDeliveryFailed and the app (or anyone) can
 *      trigger IArbitrator.redeliverRuling later. Implementations MUST:
 *        - revert if msg.sender is not the expected arbitrator;
 *        - treat ruling == 0 as "refused/default" and handle it safely;
 *        - never assume rule() arrives within any time bound.
 */
interface IArbitrable {
    /// @notice MUST be emitted by the implementation when it accepts a ruling.
    event RulingExecuted(address indexed arbitrator, uint256 indexed disputeId, uint256 ruling);

    /**
     * @notice Deliver the final ruling for a dispute this app created.
     * @param disputeId Id returned by IArbitrator.createDispute.
     * @param ruling 0 = refused/default; 1..numChoices = app-defined choice.
     */
    function rule(uint256 disputeId, uint256 ruling) external;
}

// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.28;

/**
 * @title IEligibility
 * @notice Phase-1 FROZEN juror-eligibility policy seam. The court consults this at
 *         seat-claim time; stake requirements live in the core, identity/PoP gating
 *         lives behind this interface.
 * @dev MUST be a view. The core calls it inside try/catch: a reverting or
 *      non-conforming policy makes the juror ineligible — it can never brick a dispute.
 */
interface IEligibility {
    /**
     * @notice Whether `juror` may claim seats in this court right now.
     * @param juror The staked wallet attempting a seat claim.
     */
    function isEligible(address juror) external view returns (bool);
}

// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.28;

/// ─────────────────────────────────────────────────────────────────────────────
/// Protocol-invariant constants (FROZEN for Phase 1)
/// ─────────────────────────────────────────────────────────────────────────────

/// @dev Basis-point denominator used everywhere.
uint256 constant BPS = 10_000;

/// @dev Single hardcoded court id, baked into the sortition seed for forward compat.
uint256 constant COURT_ID = 1;

/// @dev Economic guard: a slot's at-risk amount (beta*s) may be at most 3x the
///      per-seat upside (jurorFee). require(atRisk * 10000 <= upside * MAX_QSTAR_RATIO).
uint256 constant MAX_QSTAR_RATIO = 30_000;

/// @dev Max incoherence slash beta (bps of minStake). gamma is additionally capped at
///      BPS so no juror can ever lose more than one slot stake per seat.
uint256 constant MAX_SLASH_BPS = 5_000;

/// @dev Max combined app + protocol take on the arbitration fee (jurors paid first).
uint256 constant MAX_TAKE_BPS = 2_000;

/// @dev DRAW_DELAY (Created -> Drawing gap) bounds, in blocks (~6s Asset Hub blocks).
uint32 constant MIN_DRAW_DELAY_BLOCKS = 10;      // ~1 min: blunts same-block seed griefing
uint32 constant MAX_DRAW_DELAY_BLOCKS = 7_200;   // ~12 h

/// @dev Claim/commit/reveal window bounds, in blocks.
uint32 constant MIN_WINDOW_BLOCKS = 50;          // ~5 min
uint32 constant MAX_WINDOW_BLOCKS = 100_800;     // ~7 days

/// @dev Panel caps. drawTarget = ceil(panelSize * ALT_FACTOR_BPS / BPS) <= 30 seats stored.
uint16 constant MIN_PANEL_SIZE = 3;
uint16 constant MAX_PANEL_SIZE = 21;

/// @dev Ruling-choice cap K (binary + small-K only in Phase 1).
uint8 constant MAX_CHOICES = 8;

/// @dev Re-draw cap before the default ruling is applied. maxDrawAttempts in [1, cap].
uint8 constant MAX_DRAW_ATTEMPTS_CAP = 3;

/// @dev Over-draw factor: admit up to ceil(1.4 * panelSize) lowest-VRF claims
///      (primaries + alternates).
uint16 constant ALT_FACTOR_BPS = 14_000;

/// @dev Tau claim-threshold factor: tau ≈ 1.3 * panelSize / totalWeight of 2^256 space.
uint16 constant TAU_FACTOR_BPS = 13_000;

/// @dev blockhash(n) is only available for the last 256 blocks; past that the draw re-arms.
uint32 constant SEED_BLOCKHASH_HORIZON = 256;

/// ─────────────────────────────────────────────────────────────────────────────
/// Dispute state machine (FROZEN)
/// ─────────────────────────────────────────────────────────────────────────────

/// @notice Dispute lifecycle states. Settled is the only terminal state; every
///         dispute reaches it via bounded permissionless cranks.
enum DisputeState {
    None,        // 0 - sentinel: dispute does not exist
    Created,     // 1 - fee escrowed; waiting for createdBlock + drawDelayBlocks
    Drawing,     // 2 - seed fixed; seat-claim window open (re-entered on re-draw)
    Committing,  // 3 - panel admitted; commit window open
    Revealing,   // 4 - seated set frozen; reveal window open
    Tallied,     // 5 - final ruling computed (majority / tie-default / quorum-fail default)
    Ruled,       // 6 - delivery to IArbitrable attempted (success OR recorded failure)
    Settled      // 7 - terminal: slashes applied, credits assigned, fee residue routed
}

/// ─────────────────────────────────────────────────────────────────────────────
/// Court configuration (single hardcoded court, set once in the constructor)
/// ─────────────────────────────────────────────────────────────────────────────

/**
 * @notice Full economic + timing config of the one Phase-1 court.
 * @dev configHash = keccak256(abi.encode(config)) is snapshotted into each dispute at
 *      creation; settlement reads the snapshot, never live storage. All native amounts
 *      are PAS wei (plancks, 10-decimal native token).
 */
struct CourtConfig {
    address eligibility;        // IEligibility policy (PopGatedEligibility or StakeWeightedEligibility)
    uint256 minStake;           // s: stake per juror slot; weight = stakedAmount / minStake
    uint256 jurorFee;           // per-seat fee paid to coherent seats in the terminal round
    uint16 panelSize;           // seats to fill; MIN_PANEL_SIZE..MAX_PANEL_SIZE, odd recommended
    uint16 quorumBps;           // valid tally iff revealedWeight * BPS >= quorumBps * panelSize; (0, BPS]
    uint16 betaBps;             // incoherent slash, bps of minStake; <= MAX_SLASH_BPS
    uint16 gammaBps;            // silent slash, bps of minStake; betaBps <= gammaBps <= BPS
    uint16 thetaBps;            // pot share withheld from redistribution (routed to feeSink); < BPS
    uint16 appFeeBps;           // fee take credited back to the arbitrable at settlement
    uint16 protocolFeeBps;      // fee take credited to the immutable feeSink
    uint32 activationDelayBlocks; // stake usable for claims only after stakeBlock + this (anti-JIT)
    uint32 drawDelayBlocks;     // Created -> Drawing gap; MIN/MAX_DRAW_DELAY_BLOCKS bounds
    uint32 claimWindowBlocks;   // seat-claim window; MIN/MAX_WINDOW_BLOCKS bounds
    uint32 commitWindowBlocks;  // commit window; same bounds
    uint32 revealWindowBlocks;  // reveal window; same bounds
    uint8  maxDrawAttempts;     // quorum-fail re-draws before default ruling; 1..MAX_DRAW_ATTEMPTS_CAP
    uint8  defaultRuling;       // applied on tie / terminal quorum-fail; 0 = refuse, else <= MAX_CHOICES
}

/// ─────────────────────────────────────────────────────────────────────────────
/// Economic + bounds guard (FROZEN revert reasons; called once in the constructor)
/// ─────────────────────────────────────────────────────────────────────────────

error JurorsUnderpaid();            // atRisk * BPS > jurorFee * MAX_QSTAR_RATIO
error SilenceCheaperThanError();    // gammaBps < betaBps (non-reveal must cost more than being wrong)
error SlashTooHigh();               // betaBps > MAX_SLASH_BPS or gammaBps > BPS
error TakeTooHigh();                // appFeeBps + protocolFeeBps > MAX_TAKE_BPS
error PanelSizeOutOfBounds();       // panelSize outside [MIN_PANEL_SIZE, MAX_PANEL_SIZE]
error WindowOutOfBounds();          // any window outside [MIN_WINDOW_BLOCKS, MAX_WINDOW_BLOCKS]
error DrawDelayOutOfBounds();       // drawDelayBlocks outside [MIN_DRAW_DELAY_BLOCKS, MAX_DRAW_DELAY_BLOCKS]
error DrawAttemptsOutOfBounds();    // maxDrawAttempts == 0 or > MAX_DRAW_ATTEMPTS_CAP
error BadQuorum();                  // quorumBps == 0 or > BPS
error BadTheta();                   // thetaBps >= BPS
error BadDefaultRuling();           // defaultRuling > MAX_CHOICES
error ZeroStakeOrFee();             // minStake == 0 or jurorFee == 0
error ZeroEligibility();            // eligibility == address(0)

/**
 * @notice Validates a CourtConfig at deploy time. Reverts with the errors above.
 * @dev FROZEN semantics of the four economic guards:
 *        atRisk = (cfg.minStake * cfg.betaBps) / BPS;   upside = cfg.jurorFee;
 *        if (atRisk * BPS > upside * MAX_QSTAR_RATIO) revert JurorsUnderpaid();
 *        if (cfg.gammaBps < cfg.betaBps)              revert SilenceCheaperThanError();
 *        if (cfg.betaBps > MAX_SLASH_BPS || cfg.gammaBps > BPS) revert SlashTooHigh();
 *        if (uint256(cfg.appFeeBps) + cfg.protocolFeeBps > MAX_TAKE_BPS) revert TakeTooHigh();
 *      plus the structural bounds checks listed with each error.
 */
function validateCourtConfig(CourtConfig memory cfg) pure {
    if (cfg.eligibility == address(0)) revert ZeroEligibility();
    if (cfg.minStake == 0 || cfg.jurorFee == 0) revert ZeroStakeOrFee();
    if (cfg.panelSize < MIN_PANEL_SIZE || cfg.panelSize > MAX_PANEL_SIZE) revert PanelSizeOutOfBounds();
    if (cfg.quorumBps == 0 || cfg.quorumBps > BPS) revert BadQuorum();
    if (cfg.betaBps > MAX_SLASH_BPS || cfg.gammaBps > BPS) revert SlashTooHigh();
    if (cfg.gammaBps < cfg.betaBps) revert SilenceCheaperThanError();
    if (cfg.thetaBps >= BPS) revert BadTheta();
    if (uint256(cfg.appFeeBps) + cfg.protocolFeeBps > MAX_TAKE_BPS) revert TakeTooHigh();
    if (cfg.drawDelayBlocks < MIN_DRAW_DELAY_BLOCKS || cfg.drawDelayBlocks > MAX_DRAW_DELAY_BLOCKS) {
        revert DrawDelayOutOfBounds();
    }
    if (
        cfg.claimWindowBlocks < MIN_WINDOW_BLOCKS || cfg.claimWindowBlocks > MAX_WINDOW_BLOCKS ||
        cfg.commitWindowBlocks < MIN_WINDOW_BLOCKS || cfg.commitWindowBlocks > MAX_WINDOW_BLOCKS ||
        cfg.revealWindowBlocks < MIN_WINDOW_BLOCKS || cfg.revealWindowBlocks > MAX_WINDOW_BLOCKS
    ) revert WindowOutOfBounds();
    if (cfg.maxDrawAttempts == 0 || cfg.maxDrawAttempts > MAX_DRAW_ATTEMPTS_CAP) revert DrawAttemptsOutOfBounds();
    if (cfg.defaultRuling > MAX_CHOICES) revert BadDefaultRuling();
    uint256 atRisk = (cfg.minStake * cfg.betaBps) / BPS;
    if (atRisk * BPS > cfg.jurorFee * MAX_QSTAR_RATIO) revert JurorsUnderpaid();
}

// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.28;

/**
 * @title Errors
 * @notice Shared file-level custom errors for the Phase-1 GetCourt runtime paths.
 * @dev Config-guard errors (JurorsUnderpaid, SilenceCheaperThanError, etc.) live in
 *      Types.sol next to validateCourtConfig; this file holds every runtime error
 *      shared across ArbitratorCore, the policies, and the example arbitrable.
 *      P2PMarket style: parameterless custom errors, one per failure mode.
 */

/// ─────────────────────────────────────────────────────────────────────────────
/// Reentrancy + value transfer
/// ─────────────────────────────────────────────────────────────────────────────

/// @notice Reentrant call detected by the custom noReentrant modifier.
error ReentrancyGuard();

/// @notice Native .call{value:} transfer failed (withdraw / unstake refund path).
error TransferFailed();

/// ─────────────────────────────────────────────────────────────────────────────
/// Dispute lifecycle / FSM
/// ─────────────────────────────────────────────────────────────────────────────

/// @notice disputeId is 0 or beyond the monotonic counter (state == None).
error DisputeNotFound();

/// @notice The dispute is not in the state this action requires.
error WrongState();

/// @notice Action attempted before its opening block (e.g. crank before window end,
///         startDrawing at or before drawBlock).
error TooEarly();

/// @notice Action attempted after its closing block (e.g. claim/commit/reveal past
///         the window's end block).
error TooLate();

/// @notice createDispute numChoices outside [2, MAX_CHOICES].
error InvalidChoices();

/// @notice createDispute msg.value below arbitrationCost(extraData).
error FeeTooLow();

/// @notice submitEvidence with an empty URI, or evidence after the dispute left
///         the evidence-accepting states (Created..Revealing).
error InvalidEvidence();

/// @notice RESERVED (not thrown by the Phase-1 core): the core's startDrawing
///         re-arms the draw instead of reverting when blockhash(drawBlock) has
///         left the 256-block horizon. Kept for ABI stability so later cores can
///         surface the condition as an error without a breaking change.
error SeedNotReady();

/// ─────────────────────────────────────────────────────────────────────────────
/// Juror staking + seat claims (sortition)
/// ─────────────────────────────────────────────────────────────────────────────

/// @notice Eligibility policy returned false or reverted; juror may not claim seats.
error NotEligible();

/// @notice Juror's stake has not passed activationDelayBlocks yet (anti-JIT).
error StakeNotActivated();

/// @notice slotIndex >= weight(juror): juror does not own that stake slot.
error InvalidSlot();

/// @notice The (juror, slotIndex) pair already claimed a seat in this round.
error SlotAlreadyClaimed();

/// @notice ecrecover over keccak(seed, slotIndex) did not yield the juror, the
///         signature is malformed, or s is not EIP-2 low-s.
error InvalidSignature();

/// @notice vrfOutput >= round tau: the claim does not meet the sortition threshold.
error AboveThreshold();

/// ─────────────────────────────────────────────────────────────────────────────
/// Commit / reveal vote booth
/// ─────────────────────────────────────────────────────────────────────────────

/// @notice Caller holds no admitted seat in the current round (commit phase).
error NotAdmitted();

/// @notice Caller holds no seated seat in the current round (reveal phase).
error NotSeated();

/// @notice Juror already committed in this round; one commit covers all seats.
error AlreadyCommitted();

/// @notice RESERVED (not thrown by the Phase-1 core): a reveal with no stored
///         commitment surfaces as RevealMismatch (the zero commitment can never
///         match a real digest). Kept for ABI stability.
error NoCommitment();

/// @notice keccak(disputeId, juror, choice, salt) does not match the commitment.
error RevealMismatch();

/// @notice Revealed choice outside [1, numChoices].
error InvalidChoice();

/// @notice Juror already revealed in this round.
error AlreadyRevealed();

/// ─────────────────────────────────────────────────────────────────────────────
/// Ruling delivery + settlement
/// ─────────────────────────────────────────────────────────────────────────────

/// @notice redeliverRuling called after rule() has already been delivered.
error AlreadyDelivered();

/// @notice withdraw() with a zero credit balance.
error NothingToWithdraw();

/// @notice unstake would break locked-slot backing:
///         (stakedAmount - amount) < lockedSlots * minStake, or amount > stakedAmount.
error StakeLocked();

/// @notice Zero-value stake or zero-amount unstake/withdraw request.
error ZeroAmount();

// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.28;

/// ─────────────────────────────────────────────────────────────────────────────
/// Shared file-level events emitted by ArbitratorCore (Phase 1)
///
/// The three interface-level events — DisputeCreated, Ruling and
/// RulingDeliveryFailed — live in interfaces/IArbitrator.sol and are NOT
/// duplicated here. Every OTHER event the core emits is declared in this file
/// and ONLY in this file: ArbitratorCore imports it and emits these file-level
/// events directly, so this is the single authoritative off-interface ABI
/// surface for indexers. Every state change in the core emits exactly one of
/// these (or one of the interface events).
///
/// Conventions:
///  - `disputeId` and the juror/account address are indexed wherever present:
///    apps filter per dispute, jurors filter per wallet. `roundIndex` is left
///    unindexed (bounded 0..maxDrawAttempts-1, cheap to filter client-side).
///  - All native amounts are PAS wei (plancks; 10-decimal native token).
///  - `roundIndex` is incremented on every re-draw; seat-level events always
///    carry the round they belong to.
/// ─────────────────────────────────────────────────────────────────────────────

// ── Juror stake escrow ───────────────────────────────────────────────────────

/// @notice Emitted when a juror adds native stake to the escrow.
/// @param juror The staking wallet.
/// @param amount The msg.value added by this call.
/// @param newStakedAmount The juror's total staked balance after this call.
/// @param activatesAtBlock Block from which the ENTIRE balance is claim-usable
///        (block.number + activationDelayBlocks; each new stake re-arms the
///        whole balance's activation — simple anti-just-in-time rule).
event Staked(address indexed juror, uint256 amount, uint256 newStakedAmount, uint64 activatesAtBlock);

/// @notice Emitted when a juror withdraws free (non-slot-locked) stake.
/// @param juror The unstaking wallet.
/// @param amount The native amount refunded via direct transfer.
/// @param newStakedAmount The juror's total staked balance after this call.
event Unstaked(address indexed juror, uint256 amount, uint256 newStakedAmount);

/// @notice Emitted when an account pulls its accumulated withdrawable credit
///         (juror payouts, app fee cuts/residues, feeSink takes).
/// @param account The credited account that withdrew.
/// @param amount The native amount transferred out.
event Withdrawn(address indexed account, uint256 amount);

// ── Evidence (event-only; the core stores nothing) ───────────────────────────

/// @notice Emitted for every evidence submission. Callable by anyone from
///         Created until the dispute leaves Revealing; the core keeps NO
///         evidence storage — the log is the evidence record.
/// @param disputeId The dispute the evidence pertains to.
/// @param submitter msg.sender of submitEvidence.
/// @param uri Opaque evidence pointer (e.g. ipfs://...); never interpreted.
event EvidenceSubmitted(uint256 indexed disputeId, address indexed submitter, string uri);

// ── Sortition / drawing ──────────────────────────────────────────────────────

/// @notice Emitted when startDrawing found blockhash(drawBlock) already outside
///         the 256-block horizon and re-armed the draw instead. The dispute
///         stays in Created with a fresh drawBlock; no drawAttempt is consumed.
/// @param disputeId The dispute whose draw was re-armed.
/// @param newDrawBlock The new block after which startDrawing may be cranked.
event DrawingRearmed(uint256 indexed disputeId, uint64 newDrawBlock);

/// @notice Emitted when startDrawing fixes the seed and opens the seat-claim
///         window for a round.
/// @param disputeId The dispute being drawn for.
/// @param roundIndex The round this drawing belongs to.
/// @param seed keccak256(blockhash(drawBlock) ‖ disputeId ‖ COURT_ID). NOTE:
///        blockhash is collator-grindable at the margin — accepted MVP
///        randomness weakness, no secure VRF beacon exists on this chain.
/// @param totalWeightSnapshot Snapshot of totalStaked / minStake at draw time
///        (includes not-yet-activated stake; makes tau conservative).
/// @param tau Claim-admission threshold over the 2^256 VRF-output space.
event DrawingStarted(
    uint256 indexed disputeId, uint256 roundIndex, bytes32 seed, uint256 totalWeightSnapshot, uint256 tau
);

/// @notice Emitted when a seat claim is admitted into the round's lowest-VRF
///         list. It may still be evicted later by a lower claim (SeatEvicted);
///         the final panel is authoritative from DrawingClosed / PanelSeated.
/// @param disputeId The dispute claimed into.
/// @param roundIndex The round of the claim.
/// @param juror The claiming wallet (recovered signer of the slot digest).
/// @param slotIndex The juror's stake-slot index k, k < weight(juror).
/// @param vrfOutput uint256(keccak256(r ‖ s)) of the juror's signature over
///        keccak256(seed ‖ slotIndex). ECDSA nonce choice makes this grindable;
///        documented, accepted for MVP.
event SeatClaimed(
    uint256 indexed disputeId, uint256 roundIndex, address indexed juror, uint16 slotIndex, uint256 vrfOutput
);

/// @notice Emitted when a previously admitted claim is pushed out of the
///         bounded admission list by a strictly lower vrfOutput. The evicted
///         slot's lock is released; the (juror, slot) pair stays marked
///         claimed for this round.
/// @param disputeId The dispute the claim belonged to.
/// @param roundIndex The round of the eviction.
/// @param juror The evicted claim's juror.
/// @param slotIndex The evicted claim's stake-slot index.
event SeatEvicted(uint256 indexed disputeId, uint256 roundIndex, address indexed juror, uint16 slotIndex);

/// @notice Emitted when closeDrawing admits a full panel and opens the commit
///         window. Ranks 0..panelSize-1 are primaries; the rest alternates.
/// @param disputeId The dispute whose drawing closed.
/// @param roundIndex The round that closed.
/// @param admittedSeats Total admitted seats (primaries + alternates), <= drawTarget.
event DrawingClosed(uint256 indexed disputeId, uint256 roundIndex, uint256 admittedSeats);

/// @notice Emitted whenever a round dies without a valid outcome — on BOTH the
///         re-arm path (drawAttempts < maxDrawAttempts) and the terminal
///         default-ruling path (which additionally emits DefaultRulingApplied).
/// @param disputeId The dispute whose round failed.
/// @param roundIndex The round that failed.
/// @param reason Failure class: 0 = DrawShort (too few admitted seats),
///        1 = QuorumShort (revealed weight below quorum).
event QuorumFailed(uint256 indexed disputeId, uint256 roundIndex, uint8 reason);

/// @notice Emitted when the default ruling is applied as the final ruling —
///         terminal quorum-fail or terminal draw-short after maxDrawAttempts.
///         (A terminal tie also falls back to the default ruling but is
///         reported via RoundTallied.) The dispute proceeds to Tallied.
/// @param disputeId The dispute defaulted.
/// @param ruling The configured defaultRuling (0 = refused/default).
event DefaultRulingApplied(uint256 indexed disputeId, uint256 ruling);

// ── Commit / reveal vote booth ───────────────────────────────────────────────

/// @notice Emitted when an admitted juror (primary or alternate) stores their
///         vote commitment. One commit per juror covers all of the juror's
///         admitted seats in the round. The commitment itself is not logged.
/// @param disputeId The dispute committed on.
/// @param roundIndex The round of the commit.
/// @param juror The committing wallet.
event VoteCommitted(uint256 indexed disputeId, uint256 roundIndex, address indexed juror);

/// @notice Emitted when closeCommitting freezes the seated set (committed
///         primaries plus promoted committed alternates) and opens the reveal
///         window.
/// @param disputeId The dispute whose panel was seated.
/// @param roundIndex The round seated.
/// @param seatedWeight Number of seated seats; may be < panelSize when too few
///        jurors committed (quorum still divides by config panelSize, so a
///        thin panel cannot fake quorum).
event PanelSeated(uint256 indexed disputeId, uint256 roundIndex, uint256 seatedWeight);

/// @notice Emitted when a seated juror reveals a valid (choice, salt) pair
///         matching their commitment. Adds `seats` weight to tally[choice].
/// @param disputeId The dispute revealed on.
/// @param roundIndex The round of the reveal.
/// @param juror The revealing wallet.
/// @param choice The revealed choice, 1..numChoices.
/// @param seats Number of the juror's seated seats (the weight added).
event VoteRevealed(
    uint256 indexed disputeId, uint256 roundIndex, address indexed juror, uint256 choice, uint256 seats
);

// ── Tally / settlement ───────────────────────────────────────────────────────

/// @notice Emitted when closeRevealing computes the final ruling from a valid
///         tally (unique majority, or defaultRuling on a terminal tie).
/// @param disputeId The dispute tallied.
/// @param roundIndex The round that produced the tally.
/// @param finalRuling The final ruling (0 = refused/default; 1..numChoices).
/// @param revealedWeight Total seat weight revealed across all choices.
event RoundTallied(uint256 indexed disputeId, uint256 roundIndex, uint256 finalRuling, uint256 revealedWeight);

/// @notice Emitted when settle() reaches the terminal Settled state: all seat
///         outcomes applied, fee takes routed, residue credited. Terminal.
/// @param disputeId The dispute settled.
/// @param finalRuling The ruling the dispute settled under.
event DisputeSettled(uint256 indexed disputeId, uint256 finalRuling);

// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.28;

import {InvalidSignature} from "./Errors.sol";
import {BPS, COURT_ID, TAU_FACTOR_BPS} from "./Types.sol";

/**
 * @title SortitionLib
 * @notice Pure sortition math for the Phase-1 jury court: seed derivation,
 *         ecrecover-based seat-claim verification (the "poor man's VRF"), and
 *         the tau admission threshold. Compiled into ArbitratorCore as an
 *         internal library — no storage, no external calls, no cross-contract
 *         call overhead. Fully unit-testable in isolation.
 *
 * @dev How the claim "VRF" works (FROZEN for Phase 1):
 *        digest    = keccak256(abi.encodePacked(seed, uint16(slotIndex)))
 *        sig       = 65-byte secp256k1 signature (r ‖ s ‖ v) over the RAW digest
 *                    (deliberately NO EIP-191 "\x19Ethereum Signed Message" prefix —
 *                    the digest is protocol-internal, never a user-facing message)
 *        require ecrecover(digest, v, r, s) == juror   (EIP-2 low-s enforced)
 *        vrfOutput = uint256(keccak256(abi.encodePacked(r, s)))
 *      A juror is admissible iff vrfOutput < tau; the panel is the lowest-N
 *      vrfOutputs among admissible claims.
 *
 *      DOCUMENTED MVP WEAKNESSES (accepted, to be replaced behind the same seam):
 *      - ECDSA signing is nonce-malleable: a juror can grind many valid
 *        signatures over the same digest (different nonces => different (r, s))
 *        and submit the one with the lowest vrfOutput. EIP-2 low-s enforcement
 *        halves the signature space but does NOT remove grinding. The effect is
 *        capped: grinding improves a juror's seat PRIORITY among admissible
 *        claims, it never inflates vote weight beyond the juror's staked slots,
 *        and tau + lowest-N admission bound the damage.
 *      - The seed is derived from blockhash(drawBlock), which is
 *        collator/proposer-grindable at the margin. See ArbitratorCore.
 *      - Because the raw digest is signed (no EIP-191 prefix), jurors SHOULD use
 *        a dedicated claim key; never feed arbitrary third-party digests to a
 *        key that signs these claims.
 *
 *      No p+epsilon resistance is claimed anywhere in this protocol.
 */
library SortitionLib {
    /// @dev secp256k1 group order n divided by 2. EIP-2: s must be in [1, n/2]
    ///      or the signature is rejected as malleable.
    uint256 internal constant SECP256K1N_HALF =
        0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0;

    /**
     * @notice Sortition seed for one draw round.
     * @dev seed = keccak256(abi.encodePacked(blockhash(drawBlock), disputeId, COURT_ID)).
     *      COURT_ID is baked in for forward-compatibility with multi-court seeds.
     *      The caller (core) is responsible for ensuring drawBlockHash is a real
     *      blockhash within the 256-block horizon; bytes32(0) must never be passed.
     * @param drawBlockHash blockhash(drawBlock) captured by the core.
     * @param disputeId The dispute this round belongs to.
     * @return The 32-byte round seed.
     */
    function computeSeed(bytes32 drawBlockHash, uint256 disputeId) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(drawBlockHash, disputeId, COURT_ID));
    }

    /**
     * @notice The exact 32-byte digest a juror must sign to claim slot `slotIndex`.
     * @dev digest = keccak256(abi.encodePacked(seed, uint16(slotIndex))) — 34 bytes
     *      packed. Signed RAW (no EIP-191 prefix); see the library-level NatSpec.
     * @param seed Round seed from {computeSeed}.
     * @param slotIndex The juror's stake-slot index k, 0 <= k < weight(juror).
     * @return The digest to sign.
     */
    function claimDigest(bytes32 seed, uint16 slotIndex) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(seed, slotIndex));
    }

    /**
     * @notice Verifies a seat-claim signature and derives its VRF output.
     * @dev Reverts with {InvalidSignature} on ANY failure: wrong length, bad v,
     *      zero / high-s (EIP-2 malleable half), failed recovery, or recovered
     *      signer != juror. On success returns
     *      vrfOutput = uint256(keccak256(abi.encodePacked(r, s))).
     *      The tau comparison (vrfOutput < tau) is the CALLER's job — this
     *      function only authenticates the claim and derives the output.
     * @param seed Round seed from {computeSeed}.
     * @param slotIndex Stake-slot index being claimed.
     * @param juror The staked wallet that must have produced the signature.
     * @param sig 65-byte signature: r (32) ‖ s (32) ‖ v (1). v may be 27/28 or 0/1.
     * @return vrfOutput Pseudo-VRF output in [0, 2^256), uniform for honest signers.
     */
    function verifyClaim(
        bytes32 seed,
        uint16 slotIndex,
        address juror,
        bytes calldata sig
    ) internal pure returns (uint256 vrfOutput) {
        if (sig.length != 65) revert InvalidSignature();

        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (v < 27) v += 27; // normalize 0/1 encodings to 27/28
        if (v != 27 && v != 28) revert InvalidSignature();
        // EIP-2 low-s: reject s == 0 and the malleable high half of the curve order.
        if (uint256(s) == 0 || uint256(s) > SECP256K1N_HALF) revert InvalidSignature();

        // Raw digest — deliberately NOT toEthSignedMessageHash (FROZEN).
        address recovered = ecrecover(claimDigest(seed, slotIndex), v, r, s);
        if (recovered == address(0) || recovered != juror) revert InvalidSignature();

        vrfOutput = uint256(keccak256(abi.encodePacked(r, s)));
    }

    /**
     * @notice Claim-admission threshold tau for a round.
     * @dev tau = floor(type(uint256).max * (panelSize * TAU_FACTOR_BPS) / (totalWeight * BPS)),
     *      i.e. a TAU_FACTOR_BPS/BPS (~1.3x) oversampled fraction of the 2^256
     *      output space, so ~1.3 * panelSize claims are expected in each round.
     *      Saturating: if totalWeight == 0, or the expected claim fraction >= 1
     *      (tiny totalWeight), tau = type(uint256).max and every valid claim is
     *      admissible — lowest-N admission then does all the work.
     *      NOTE (documented, accepted): the core snapshots totalWeight INCLUDING
     *      not-yet-activated stake, which only makes tau conservative (smaller).
     * @param panelSize Configured panel size (core guarantees >= MIN_PANEL_SIZE).
     * @param totalWeight Snapshot of total staked slots (totalStaked / minStake).
     * @return tau Threshold; a claim is admissible iff vrfOutput < tau.
     */
    function tauThreshold(uint16 panelSize, uint256 totalWeight) internal pure returns (uint256 tau) {
        if (totalWeight == 0) return type(uint256).max;
        uint256 numerator = uint256(panelSize) * TAU_FACTOR_BPS; // <= 65535 * 13000, no overflow
        if (totalWeight <= type(uint256).max / BPS) {
            return saturatingMulDiv(type(uint256).max, numerator, totalWeight * BPS);
        }
        // totalWeight * BPS would overflow uint256. Exact fallback via the floor
        // identity floor(floor(x / tw) / BPS) == floor(x / (tw * BPS)):
        return saturatingMulDiv(type(uint256).max, numerator, totalWeight) / BPS;
    }

    /**
     * @notice floor(x * y / denominator) with a full 512-bit intermediate,
     *         saturating at type(uint256).max instead of reverting.
     * @dev Based on the well-known Remco Bloemen mulDiv (as used by OZ Math),
     *      restated without inline assembly. Differences from the classic
     *      version (FROZEN semantics for this library):
     *        - result >= 2^256  => returns type(uint256).max (saturate, no revert)
     *        - denominator == 0 => returns type(uint256).max (treated as "no bound")
     *      Total function: never reverts, never panics.
     * @param x First factor.
     * @param y Second factor.
     * @param denominator Divisor.
     * @return result min(floor(x * y / denominator), type(uint256).max).
     */
    function saturatingMulDiv(uint256 x, uint256 y, uint256 denominator) internal pure returns (uint256 result) {
        unchecked {
            // 512-bit product: [prod1 prod0] = x * y.
            // mulmod over 2^256 - 1 recovers the high limb (Chinese-remainder trick).
            uint256 prod0 = x * y; // low 256 bits (wrapping)
            uint256 mm = mulmod(x, y, type(uint256).max);
            uint256 prod1 = mm - prod0; // high 256 bits...
            if (mm < prod0) prod1 -= 1; // ...with borrow

            // Short-circuit: product fits in 256 bits.
            if (prod1 == 0) {
                if (denominator == 0) return type(uint256).max;
                return prod0 / denominator;
            }

            // Saturate when the quotient would not fit in 256 bits
            // (also covers denominator == 0 since prod1 > 0 here).
            if (denominator <= prod1) return type(uint256).max;

            // Make the 512-bit number exactly divisible by denominator:
            // [prod1 prod0] -= (x * y) mod denominator.
            uint256 remainder = mulmod(x, y, denominator);
            if (remainder > prod0) prod1 -= 1;
            prod0 -= remainder;

            // Factor powers of two out of denominator.
            uint256 twos = denominator & (0 - denominator);
            denominator /= twos;
            prod0 /= twos;
            // Fold the bits shifted out of prod1 into prod0: 2^256 / twos.
            prod0 |= prod1 * (((0 - twos) / twos) + 1);

            // Modular inverse of the (now odd) denominator mod 2^256 by
            // Newton-Raphson: each step doubles the number of correct bits.
            uint256 inverse = (3 * denominator) ^ 2; // 4 correct bits
            inverse *= 2 - denominator * inverse; // 8
            inverse *= 2 - denominator * inverse; // 16
            inverse *= 2 - denominator * inverse; // 32
            inverse *= 2 - denominator * inverse; // 64
            inverse *= 2 - denominator * inverse; // 128
            inverse *= 2 - denominator * inverse; // 256

            // Exact division: multiply by the inverse.
            result = prod0 * inverse;
        }
    }
}

