pragma solidity ^0.8.28;

import {BPS, CourtConfig} from "./Types.sol";

/**
 * @title SettlementLib
 * @notice Pure settlement math for the Phase-1 jury protocol, per the FROZEN
 *         dispute-FSM spec. Internal library: no storage, no events, no external
 *         calls — every function is `pure` and fully unit/fuzz-testable in
 *         isolation.
 *
 * @dev All native amounts are PAS wei (plancks; 10-decimal native token).
 *
 *      Formulas implemented (FROZEN):
 *        - arbitrationCost = ceilDiv(panelSize * jurorFee * BPS,
 *                                    BPS - appFeeBps - protocolFeeBps)
 *          Grossed up so that after the app + protocol takes are removed, the
 *          remainder always covers panelSize full jurorFees ("jurors paid first").
 *        - pot P = slash(beta) * |incoherent| + slash(gamma) * |silent|
 *        - coherent per-seat payout = jurorFee
 *                                   + floor(floor(P * (BPS - theta) / BPS) / |coherent|)
 *          with all floor-division dust (theta share + rounding) routed to the
 *          feeSink by the caller.
 *        - slash(rate) = floor(minStake * rateBps / BPS)
 *        - feeTakes = (floor(cost * appFeeBps / BPS), floor(cost * protocolFeeBps / BPS))
 *
 *      SOLVENCY (never mint), given a CourtConfig that passed validateCourtConfig:
 *        (1) arbitrationCostOf: cost * (BPS - appFeeBps - protocolFeeBps)
 *            >= panelSize * jurorFee * BPS, and the takes are floored, so
 *            cost - appCut - protocolCut >= panelSize * jurorFee. The prepaid fee
 *            pool always covers every possible jurorFee payout plus both takes.
 *        (2) coherentPayout: perSeat * coherentW + dust
 *            == jurorFee * coherentW + pot. The pot side is exactly conserved
 *            (redistributed + dust == pot); the jurorFee side is covered by (1)
 *            because coherentW <= panelSize. Nothing is ever created.
 *        (3) potOf / slashOf: slashes are floored, so the amount credited into
 *            the pot never exceeds the stake actually deducted from jurors.
 *
 *      Preconditions (enforced upstream by validateCourtConfig at deploy; this
 *      library does not re-validate — out-of-range inputs simply revert on
 *      checked arithmetic, e.g. thetaBps > BPS underflows):
 *        - appFeeBps + protocolFeeBps <= MAX_TAKE_BPS < BPS  (denominator > 0)
 *        - thetaBps < BPS
 *        - betaBps <= MAX_SLASH_BPS, gammaBps <= BPS, gammaBps >= betaBps
 */
library SettlementLib {
    /**
     * @notice Gross arbitration fee the arbitrable must prepay for one dispute.
     * @dev cost = ceilDiv(panelSize * jurorFee * BPS, BPS - appFeeBps - protocolFeeBps).
     *      Ceil rounding puts the (at most 1 wei) gross-up error on the app, never
     *      on the jurors. Phase-1: constant per config; extraData never enters.
     *      The core calls this ONCE in its constructor and caches the result in an
     *      immutable, so an absurd jurorFee that would overflow the numerator
     *      fails loudly at deploy instead of bricking createDispute at runtime.
     * @param cfg The court config the dispute is created under (snapshot source).
     * @return cost Required msg.value floor for createDispute, in PAS wei.
     */
    function arbitrationCostOf(CourtConfig memory cfg) internal pure returns (uint256 cost) {
        // > 0 by validateCourtConfig: appFeeBps + protocolFeeBps <= MAX_TAKE_BPS < BPS.
        uint256 denominator = BPS - uint256(cfg.appFeeBps) - uint256(cfg.protocolFeeBps);
        cost = _ceilDiv(uint256(cfg.panelSize) * cfg.jurorFee * BPS, denominator);
    }

    /**
     * @notice Redistribution pot P collected from a round's misbehaving seats.
     * @dev P = slash(beta) * incoherentW + slash(gamma) * silentW. Uses the same
     *      floored per-seat slash as slashOf, so the pot equals exactly the sum
     *      actually deducted from juror stakes — never more.
     * @param minStake    Slot stake s from the snapshot config.
     * @param betaBps     Incoherence slash rate (bps of minStake).
     * @param gammaBps    Silence slash rate (bps of minStake); >= betaBps by guard.
     * @param incoherentW Number of incoherent seats (revealed a losing choice).
     * @param silentW     Number of silent seats (never committed / never revealed).
     * @return pot Total slashed amount available for redistribution, in PAS wei.
     */
    function potOf(
        uint256 minStake,
        uint16 betaBps,
        uint16 gammaBps,
        uint256 incoherentW,
        uint256 silentW
    ) internal pure returns (uint256 pot) {
        pot = slashOf(minStake, betaBps) * incoherentW + slashOf(minStake, gammaBps) * silentW;
    }

    /**
     * @notice Per-seat payout for a coherent (or tie-case revealed) seat, plus the
     *         dust routed to the feeSink.
     * @dev redistributed = floor(pot * (BPS - thetaBps) / BPS);
     *      perSeat = jurorFee + floor(redistributed / coherentW);
     *      dust    = pot - floor(redistributed / coherentW) * coherentW
     *              = theta share + all floor-division remainders.
     *      Conservation (FROZEN): perSeat * coherentW + dust
     *                             == jurorFee * coherentW + pot, always.
     *      Edge case coherentW == 0 (possible only in rounds this function is not
     *      called for, but kept total for fuzzing): returns (0, pot) — nobody is
     *      paid, the whole pot is dust to the feeSink, and no division by zero.
     *      Failed-round finalization reuses this with jurorFee == 0 (no fee in a
     *      failed round; revealed seats still share the pot).
     * @param jurorFee  Per-seat fee from the snapshot config (terminal round only).
     * @param pot       Redistribution pot P from potOf.
     * @param thetaBps  Pot share withheld for the feeSink; < BPS by guard.
     * @param coherentW Number of seats sharing the pot (coherent, or all revealed
     *                  seats in the terminal-tie case).
     * @return perSeat Credit per coherent seat (jurorFee + pot share), in PAS wei.
     * @return dust    Remainder of the pot routed to the feeSink, in PAS wei.
     */
    function coherentPayout(
        uint256 jurorFee,
        uint256 pot,
        uint16 thetaBps,
        uint256 coherentW
    ) internal pure returns (uint256 perSeat, uint256 dust) {
        if (coherentW == 0) {
            return (0, pot);
        }
        uint256 redistributed = (pot * (BPS - uint256(thetaBps))) / BPS;
        uint256 potShare = redistributed / coherentW;
        perSeat = jurorFee + potShare;
        dust = pot - potShare * coherentW;
    }

    /**
     * @notice Amount slashed from one seat's locked slot stake at the given rate.
     * @dev floor(minStake * rateBps / BPS). With rateBps <= BPS (guarded at deploy)
     *      the result is <= minStake, upholding the invariant that no juror ever
     *      loses more than one locked slot stake per seat.
     * @param minStake Slot stake s from the snapshot config.
     * @param rateBps  betaBps (incoherent) or gammaBps (silent).
     * @return amount Slash amount in PAS wei.
     */
    function slashOf(uint256 minStake, uint16 rateBps) internal pure returns (uint256 amount) {
        amount = (minStake * uint256(rateBps)) / BPS;
    }

    /**
     * @notice App and protocol takes on the gross arbitration cost.
     * @dev Both floored, so appCut + protocolCut <= cost * (appFeeBps + protocolFeeBps) / BPS,
     *      which together with the ceil gross-up in arbitrationCostOf guarantees
     *      cost - appCut - protocolCut >= panelSize * jurorFee (jurors paid first).
     * @param cost           Gross arbitration cost the app prepaid (arbitrationCostOf).
     * @param appFeeBps      Take credited back to the arbitrable at settlement.
     * @param protocolFeeBps Take credited to the immutable feeSink.
     * @return appCut      App's fee credit, in PAS wei.
     * @return protocolCut Protocol feeSink's fee credit, in PAS wei.
     */
    function feeTakes(
        uint256 cost,
        uint16 appFeeBps,
        uint16 protocolFeeBps
    ) internal pure returns (uint256 appCut, uint256 protocolCut) {
        appCut = (cost * uint256(appFeeBps)) / BPS;
        protocolCut = (cost * uint256(protocolFeeBps)) / BPS;
    }

    /**
     * @dev ceil(a / b). Reverts on b == 0 (division by zero) — callers guarantee
     *      a positive denominator via validateCourtConfig. The a == 0 branch
     *      avoids the underflow in (a - 1).
     */
    function _ceilDiv(uint256 a, uint256 b) private pure returns (uint256) {
        if (a == 0) return 0;
        return (a - 1) / b + 1;
    }
}

