pragma solidity ^0.8.28;

import {IArbitrator} from "../interfaces/IArbitrator.sol";
import {IArbitrable} from "../interfaces/IArbitrable.sol";
import {IEligibility} from "../interfaces/IEligibility.sol";
import "../lib/Types.sol";
import "../lib/Errors.sol";
import "../lib/Events.sol";
import {SortitionLib} from "../lib/SortitionLib.sol";
import {SettlementLib} from "../lib/SettlementLib.sol";

/**
 * @title ArbitratorCore
 * @notice Phase-1 GetCourt court. One hardcoded court (config frozen in
 *         the constructor), binary/small-K rulings, PoP-gateable juries. The contract
 *         embeds, as internal sections of a single contract to minimise cross-contract
 *         fragility in v1 (extractable behind the same seams later):
 *           - juror stake escrow      (payable native-PAS escrow; NO fungible holds on
 *                                      pallet-revive, so stake is held by this contract);
 *           - sortition               (ecrecover-signature "VRF" seat claims via
 *                                      SortitionLib, bounded sorted admission list,
 *                                      lowest-output-wins);
 *           - commit/reveal vote booth;
 *           - tally + settlement      (SettlementLib math, pull-payment credits,
 *                                      redistributive slashing).
 *
 *         The protocol never interprets what a dispute is about: choices are opaque
 *         uint8 indices, evidence is event-only, extraData is echoed untouched.
 *
 * @dev LIVENESS: every transition after Created is a permissionless crank; from any
 *      state at most (maxDrawAttempts * 4 + 3) cranks reach Settled. No path depends
 *      on the arbitrable app, the eligibility policy, or any specific juror acting.
 *      The only external calls out of this contract are IArbitrable.rule (try/catch),
 *      IEligibility.isEligible (try/catch), and native transfers under the custom
 *      noReentrant guard (pull-only withdraw / unstake). No owner, no admin, no
 *      upgrade path, no protocol token.
 *
 *      DOCUMENTED MVP RANDOMNESS/SORTITION WEAKNESSES (accepted for Phase 1; no
 *      secure on-chain VRF/randomness beacon exists on this chain):
 *        1. The draw seed is keccak256(blockhash(drawBlock), disputeId, COURT_ID).
 *           blockhash is collator/proposer-grindable at the margin, and the cranker
 *           of startDrawing can, within the 255-block horizon, time the crank.
 *           drawDelayBlocks >= MIN_DRAW_DELAY_BLOCKS blunts same-block griefing only.
 *        2. The per-slot "VRF" is an ECDSA signature over keccak256(seed, slotIndex).
 *           ECDSA signing is nonce-malleable, so a juror can grind many signatures
 *           over the same digest hunting a lower vrfOutput. EIP-2 low-s halves the
 *           space but does not remove grinding. tau plus lowest-N admission caps the
 *           damage to seat priority, never vote weight. A real VRF replaces this
 *           later behind the same claim seam (SortitionLib.verifyClaim).
 *        3. totalWeight used for tau includes not-yet-activated stake, making tau
 *           slightly conservative (fewer claims pass than ideal). Accepted.
 *      No p+epsilon-resistance is claimed anywhere.
 *
 *      SOLVENCY INVARIANT: settlement never mints — every credit is drawn from the
 *      dispute's prepaid feePool or from stake actually slashed in this contract, so
 *      sum(credits) + totalStaked + un-settled feePools <= address(this).balance.
 *      No juror ever loses more than the minStake locked per seat
 *      (gammaBps <= BPS ==> max loss per seat = minStake * gammaBps / BPS <= minStake).
 */
contract ArbitratorCore is IArbitrator {
    // ─────────────────────────────────────────────────────────────────────────
    // Local types
    // ─────────────────────────────────────────────────────────────────────────

    /// @dev Seat lifecycle inside one round.
    ///      Admitted: in the sorted claim list during Drawing.
    ///      Seated:   on the deciding panel after alternate promotion (commit walk).
    ///      Silent:   primary whose juror never committed (gamma-slashed at finalization).
    ///      Released: alternate never seated (unslashed, lock released at closeCommitting).
    enum SeatStatus {
        Admitted,
        Seated,
        Silent,
        Released
    }

    /// @dev One admitted claim. Array kept sorted ascending by vrfOutput during the
    ///      claim window; after closeDrawing the array index IS the seat's rank.
    struct Seat {
        address juror;
        uint16 slotIndex;
        SeatStatus status;
        uint256 vrfOutput;
    }

    /// @dev Per-round sortition + vote-booth state. Rounds are never revisited: a
    ///      failed round is finalized where it fails and a fresh Round struct is used.
    struct Round {
        bytes32 seed;
        uint256 tau;
        uint256 totalWeightSnapshot;
        uint64 claimEndBlock;
        uint64 commitEndBlock;
        uint64 revealEndBlock;
        uint16 drawTarget;
        uint16 seatedCount;
        uint256 revealedWeight;
        Seat[] seats;
        mapping(address => uint256) admittedSeats;
        mapping(address => uint256) seatedSeats;
        mapping(address => bytes32) commitments;
        mapping(address => uint256) revealedChoice; // 0 = not revealed
        mapping(uint256 => uint256) tallyWeight;    // choice => seated seats revealed for it
        mapping(bytes32 => bool) slotClaimed;       // keccak(juror, slotIndex) => claimed this round
    }

    struct Dispute {
        address arbitrable;
        uint8 numChoices;
        DisputeState state;
        uint8 drawAttempts;
        uint8 terminalKind; // TK_* — how the final ruling was reached
        bool delivered;
        uint32 roundIndex;  // current (or final) round
        uint64 createdBlock;
        uint64 drawBlock;
        bytes32 configHashSnapshot;
        uint256 feePool;    // exactly arbitrationCost, escrowed at creation
        uint256 finalRuling;
    }

    struct Juror {
        uint256 stakedAmount;
        uint256 lockedSlots;
        uint64 activatesAtBlock;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Local errors (shared runtime errors live in lib/Errors.sol)
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice slotIndices and sigs arrays differ in length.
    error LengthMismatch();
    /// @notice Juror has no unlocked minStake slot left to back this seat.
    error NoFreeSlot();
    /// @notice Claim passed tau but the admission list is full of lower outputs.
    error ClaimNotCompetitive();
    /// @notice commitVote with bytes32(0) (reserved as "no commitment").
    error EmptyCommitment();
    /// @notice feeSink constructor arg is the zero address.
    error ZeroFeeSink();

    // ─────────────────────────────────────────────────────────────────────────
    // Constants
    // ─────────────────────────────────────────────────────────────────────────

    // How the final ruling was reached (Dispute.terminalKind).
    uint8 private constant TK_MAJORITY = 0;    // unique weighted-majority winner
    uint8 private constant TK_TIE = 1;         // quorum met, tie -> defaultRuling
    uint8 private constant TK_QUORUM_FAIL = 2; // re-draws exhausted at reveal quorum
    uint8 private constant TK_DRAW_SHORT = 3;  // re-draws exhausted at seat admission

    // QuorumFailed reasons.
    uint8 private constant REASON_DRAW_SHORT = 0;
    uint8 private constant REASON_NO_QUORUM = 1;

    // ─────────────────────────────────────────────────────────────────────────
    // Storage
    // ─────────────────────────────────────────────────────────────────────────

    /// @dev The single Phase-1 court config. Set once in the constructor, never
    ///      mutated; configHash() is snapshotted into every dispute at creation and
    ///      settlement reads only config values (== the snapshot, by immutability).
    CourtConfig private _config;

    /// @dev keccak256(abi.encode(_config)), fixed at deploy.
    bytes32 private immutable _configHash;

    /// @dev Constant Phase-1 arbitration cost, computed once at deploy
    ///      (SettlementLib.arbitrationCostOf). Computing it in the constructor makes
    ///      an overflowing panelSize * jurorFee * BPS product fail at deploy instead
    ///      of bricking createDispute at runtime.
    uint256 private immutable _arbCost;

    /// @notice Immutable recipient of the protocol fee cut, theta pot share and dust.
    address public immutable feeSink;

    uint256 private _disputeCount; // ids start at 1; 0 is the null dispute

    mapping(uint256 => Dispute) private _disputes;
    mapping(uint256 => mapping(uint256 => Round)) private _rounds; // disputeId => roundIndex => Round

    mapping(address => Juror) private _jurors;

    /// @notice Total native PAS currently staked by all jurors (escrowed here).
    /// @dev totalWeight for tau = totalStaked / minStake — includes not-yet-activated
    ///      stake (documented weakness #3, conservative).
    uint256 public totalStaked;

    /// @dev Pull-payment credits: juror payouts, app fee cuts/residues + createDispute
    ///      overpayments, feeSink cuts.
    mapping(address => uint256) private _credits;

    /// @dev Custom reentrancy guard (P2PMarket style — not OZ).
    bool private _reentrancyLock;

    modifier noReentrant() {
        if (_reentrancyLock) revert ReentrancyGuard();
        _reentrancyLock = true;
        _;
        _reentrancyLock = false;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Constructor
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @param cfg Full court config; validated by validateCourtConfig (economic guards:
     *            jurors-underpaid ratio, gamma >= beta, slash caps, take caps, bounds).
     * @param feeSink_ Immutable recipient of protocol fee, theta share and dust.
     */
    constructor(CourtConfig memory cfg, address feeSink_) {
        if (feeSink_ == address(0)) revert ZeroFeeSink();
        validateCourtConfig(cfg);
        _config = cfg;
        _configHash = keccak256(abi.encode(cfg));
        _arbCost = SettlementLib.arbitrationCostOf(cfg);
        feeSink = feeSink_;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Juror stake escrow (native PAS; pallet-revive has no fungible holds)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Escrow native stake. Each call re-arms activation for the WHOLE balance
     *         to block.number + activationDelayBlocks (simple anti-just-in-time rule).
     * @dev weight(juror) = stakedAmount / minStake; each weight unit is an
     *      independently claimed, independently slashed slot.
     */
    function stake() external payable noReentrant {
        if (msg.value == 0) revert ZeroAmount();
        Juror storage j = _jurors[msg.sender];
        j.stakedAmount += msg.value;
        j.activatesAtBlock = uint64(block.number + _config.activationDelayBlocks);
        totalStaked += msg.value;
        emit Staked(msg.sender, msg.value, j.stakedAmount, j.activatesAtBlock);
    }

    /**
     * @notice Withdraw un-locked stake. The remainder must keep backing every locked
     *         slot: stakedAmount - amount >= lockedSlots * minStake.
     */
    function unstake(uint256 amount) external noReentrant {
        if (amount == 0) revert ZeroAmount();
        Juror storage j = _jurors[msg.sender];
        if (amount > j.stakedAmount || j.stakedAmount - amount < j.lockedSlots * _config.minStake) {
            revert StakeLocked();
        }
        j.stakedAmount -= amount;
        totalStaked -= amount;
        emit Unstaked(msg.sender, amount, j.stakedAmount);
        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        if (!ok) revert TransferFailed();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // IArbitrator: dispute creation + cost
    // ─────────────────────────────────────────────────────────────────────────

    /// @inheritdoc IArbitrator
    /// @dev Exactly arbitrationCost is escrowed as the dispute's feePool; any excess
    ///      msg.value is credited to the caller's withdrawable balance immediately
    ///      (pull via withdraw()), never pushed back — per the FROZEN seam doc.
    function createDispute(uint8 numChoices, bytes calldata extraData)
        external
        payable
        noReentrant
        returns (uint256 disputeId)
    {
        if (numChoices < 2 || numChoices > MAX_CHOICES) revert InvalidChoices();
        uint256 cost = _arbCost;
        if (msg.value < cost) revert FeeTooLow();

        disputeId = ++_disputeCount;
        Dispute storage d = _disputes[disputeId];
        d.arbitrable = msg.sender;
        d.numChoices = numChoices;
        d.state = DisputeState.Created;
        d.createdBlock = uint64(block.number);
        d.drawBlock = uint64(block.number + _config.drawDelayBlocks);
        d.configHashSnapshot = _configHash;
        d.feePool = cost;

        if (msg.value > cost) {
            _credits[msg.sender] += msg.value - cost;
        }

        emit DisputeCreated(disputeId, msg.sender, numChoices, _configHash, extraData);
    }

    /// @inheritdoc IArbitrator
    /// @dev Constant for the Phase-1 court; extraData kept in the seam but ignored.
    ///      Grossed up so jurors are paid first even after app + protocol takes:
    ///      cost = ceil(panelSize * jurorFee * BPS / (BPS - appFeeBps - protocolFeeBps));
    ///      the denominator is >= BPS - MAX_TAKE_BPS > 0 by the deploy guard.
    function arbitrationCost(bytes calldata) external view returns (uint256 cost) {
        return _arbCost;
    }

    /**
     * @notice Evidence is event-only: anyone may reference an URI from Created until
     *         the dispute leaves Revealing. Nothing is stored on-chain.
     */
    function submitEvidence(uint256 disputeId, string calldata evidenceURI) external {
        Dispute storage d = _getDispute(disputeId);
        if (bytes(evidenceURI).length == 0) revert InvalidEvidence();
        if (uint8(d.state) > uint8(DisputeState.Revealing)) revert InvalidEvidence();
        emit EvidenceSubmitted(disputeId, msg.sender, evidenceURI);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // FSM: Created -> Drawing (seed fixing)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Permissionless crank: fixes the sortition seed and opens the seat-claim
     *         window. If blockhash(drawBlock) has left the 256-block horizon the draw
     *         re-arms (new drawBlock, no drawAttempt consumed) — any single crank
     *         within the horizon of a drawBlock proceeds, so liveness holds.
     * @dev WEAKNESS (documented, accepted): blockhash is proposer-grindable at the
     *      margin and a cranker can time this call inside the horizon. See contract
     *      NatSpec, weakness #1.
     */
    function startDrawing(uint256 disputeId) external {
        Dispute storage d = _getDispute(disputeId);
        if (d.state != DisputeState.Created) revert WrongState();
        if (block.number <= d.drawBlock) revert TooEarly();

        if (block.number >= uint256(d.drawBlock) + SEED_BLOCKHASH_HORIZON) {
            d.drawBlock = uint64(block.number + _config.drawDelayBlocks);
            emit DrawingRearmed(disputeId, d.drawBlock);
            return; // stays Created; repeatable, never consumes a drawAttempt
        }
        bytes32 bh = blockhash(d.drawBlock);
        if (bh == bytes32(0)) {
            // Defensive: host returned no hash inside the horizon — re-arm.
            d.drawBlock = uint64(block.number + _config.drawDelayBlocks);
            emit DrawingRearmed(disputeId, d.drawBlock);
            return;
        }

        Round storage r = _rounds[disputeId][d.roundIndex];
        r.seed = SortitionLib.computeSeed(bh, disputeId);
        r.totalWeightSnapshot = totalStaked / _config.minStake;
        r.tau = SortitionLib.tauThreshold(_config.panelSize, r.totalWeightSnapshot);
        r.claimEndBlock = uint64(block.number + _config.claimWindowBlocks);
        r.drawTarget = uint16(_ceilDiv(uint256(_config.panelSize) * ALT_FACTOR_BPS, BPS));

        d.state = DisputeState.Drawing;
        emit DrawingStarted(disputeId, d.roundIndex, r.seed, r.totalWeightSnapshot, r.tau);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // FSM: Drawing — pull-based seat claims (ecrecover-signature "VRF")
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Claim panel seats for stake slots. For each slot k the juror signs
     *         digest = keccak256(abi.encodePacked(seed, uint16(k))) with their wallet
     *         key (raw digest — NO EIP-191 prefix; FROZEN); the contract recovers the
     *         signer and uses vrfOutput = uint256(keccak256(abi.encodePacked(r, s)))
     *         for lowest-output admission. Claims only make sense when
     *         vrfOutput < tau ~= 1.3 * panelSize / totalWeight of the 2^256 space.
     * @dev Admission list is sorted ascending and bounded at drawTarget =
     *      ceil(1.4 * panelSize) seats; a full list evicts its highest entry iff the
     *      new output is strictly lower (evicted slot lock released; the evicted
     *      (juror, slot) pair stays marked claimed for this round). Each admitted
     *      seat locks exactly one minStake slot until its round is finalized.
     *      A reverting/false eligibility policy only blocks claims — never bricks.
     *      WEAKNESS (documented, accepted): signature nonce grinding — see contract
     *      NatSpec, weakness #2.
     */
    function claimSeats(uint256 disputeId, uint16[] calldata slotIndices, bytes[] calldata sigs) external {
        Dispute storage d = _getDispute(disputeId);
        if (d.state != DisputeState.Drawing) revert WrongState();
        Round storage r = _rounds[disputeId][d.roundIndex];
        if (block.number > r.claimEndBlock) revert TooLate();
        if (slotIndices.length != sigs.length) revert LengthMismatch();

        Juror storage j = _jurors[msg.sender];
        if (block.number < j.activatesAtBlock) revert StakeNotActivated();

        bool eligible;
        try IEligibility(_config.eligibility).isEligible(msg.sender) returns (bool res) {
            eligible = res;
        } catch {
            eligible = false;
        }
        if (!eligible) revert NotEligible();

        uint256 w = j.stakedAmount / _config.minStake;
        uint256 n = slotIndices.length;
        for (uint256 i; i < n; ++i) {
            uint16 k = slotIndices[i];
            if (k >= w) revert InvalidSlot();
            bytes32 slotKey = keccak256(abi.encodePacked(msg.sender, k));
            if (r.slotClaimed[slotKey]) revert SlotAlreadyClaimed();
            uint256 vrf = SortitionLib.verifyClaim(r.seed, k, msg.sender, sigs[i]);
            if (vrf >= r.tau) revert AboveThreshold();
            r.slotClaimed[slotKey] = true;
            _admitClaim(disputeId, d.roundIndex, r, k, vrf);
        }
    }

    /// @dev Inserts (msg.sender, k, vrf) into the round's bounded sorted list,
    ///      evicting the current highest output if the list is full.
    function _admitClaim(uint256 disputeId, uint32 roundIndex, Round storage r, uint16 k, uint256 vrf) private {
        uint256 len = r.seats.length;
        if (len >= r.drawTarget) {
            Seat storage last = r.seats[len - 1];
            if (vrf >= last.vrfOutput) revert ClaimNotCompetitive();
            address evictedJuror = last.juror;
            uint16 evictedSlot = last.slotIndex;
            _jurors[evictedJuror].lockedSlots -= 1;
            r.admittedSeats[evictedJuror] -= 1;
            r.seats.pop();
            len -= 1;
            emit SeatEvicted(disputeId, roundIndex, evictedJuror, evictedSlot);
        }

        Juror storage j = _jurors[msg.sender];
        if ((j.lockedSlots + 1) * _config.minStake > j.stakedAmount) revert NoFreeSlot();
        j.lockedSlots += 1;
        r.admittedSeats[msg.sender] += 1;

        r.seats.push();
        uint256 pos = len;
        while (pos > 0 && r.seats[pos - 1].vrfOutput > vrf) {
            r.seats[pos] = r.seats[pos - 1];
            pos -= 1;
        }
        Seat storage seat = r.seats[pos];
        seat.juror = msg.sender;
        seat.slotIndex = k;
        seat.vrfOutput = vrf;
        seat.status = SeatStatus.Admitted;

        emit SeatClaimed(disputeId, roundIndex, msg.sender, k, vrf);
    }

    /**
     * @notice Permissionless crank closing the claim window. Enough seats: ranks are
     *         fixed (array order), commit window opens. Too few: all admitted slot
     *         locks are released unslashed and the draw either re-arms (drawAttempts
     *         not exhausted) or the default ruling is applied terminally.
     */
    function closeDrawing(uint256 disputeId) external {
        Dispute storage d = _getDispute(disputeId);
        if (d.state != DisputeState.Drawing) revert WrongState();
        Round storage r = _rounds[disputeId][d.roundIndex];
        if (block.number <= r.claimEndBlock) revert TooEarly();

        uint256 admitted = r.seats.length;
        if (admitted >= _config.panelSize) {
            r.commitEndBlock = uint64(block.number + _config.commitWindowBlocks);
            d.state = DisputeState.Committing;
            emit DrawingClosed(disputeId, d.roundIndex, admitted);
        } else {
            for (uint256 i; i < admitted; ++i) {
                _jurors[r.seats[i].juror].lockedSlots -= 1;
            }
            _failRound(disputeId, d, REASON_DRAW_SHORT, TK_DRAW_SHORT);
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // FSM: Committing — commit phase (alternates commit speculatively)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Commit a vote. One commitment covers ALL of the caller's admitted seats
     *         in this round (primaries and alternates alike — alternates commit
     *         speculatively in case they are promoted).
     * @dev commitment = keccak256(abi.encodePacked(disputeId, juror, choice, salt))
     *      with choice as uint256 and salt as bytes32 (FROZEN formula). Clients MUST
     *      use a fresh salt per round: the formula does not bind the roundIndex, so
     *      reusing a revealed (choice, salt) pair in a later round of the same
     *      dispute publicly telegraphs the vote. bytes32(0) is reserved for
     *      "no commitment".
     */
    function commitVote(uint256 disputeId, bytes32 commitment) external {
        Dispute storage d = _getDispute(disputeId);
        if (d.state != DisputeState.Committing) revert WrongState();
        Round storage r = _rounds[disputeId][d.roundIndex];
        if (block.number > r.commitEndBlock) revert TooLate();
        if (commitment == bytes32(0)) revert EmptyCommitment();
        if (r.admittedSeats[msg.sender] == 0) revert NotAdmitted();
        if (r.commitments[msg.sender] != bytes32(0)) revert AlreadyCommitted();
        r.commitments[msg.sender] = commitment;
        emit VoteCommitted(disputeId, d.roundIndex, msg.sender);
    }

    /**
     * @notice Permissionless crank closing the commit window and seating the panel.
     * @dev FROZEN promotion walk: seats in ascending rank; a seat is SEATED iff its
     *      juror committed, until panelSize seats are seated or seats run out.
     *      Primaries whose juror never committed are marked SILENT (they had the
     *      duty; gamma-slashed at round finalization) and are effectively replaced
     *      by the lowest-rank committed alternates. All never-seated alternates are
     *      released unslashed here. seatedWeight may be < panelSize; the reveal
     *      quorum still divides by panelSize, so a thin panel cannot fake quorum.
     */
    function closeCommitting(uint256 disputeId) external {
        Dispute storage d = _getDispute(disputeId);
        if (d.state != DisputeState.Committing) revert WrongState();
        Round storage r = _rounds[disputeId][d.roundIndex];
        if (block.number <= r.commitEndBlock) revert TooEarly();

        uint256 len = r.seats.length;
        uint16 target = _config.panelSize;
        uint16 seated;
        for (uint256 i; i < len; ++i) {
            Seat storage s = r.seats[i];
            bool committed = r.commitments[s.juror] != bytes32(0);
            if (committed && seated < target) {
                s.status = SeatStatus.Seated;
                seated += 1;
                r.seatedSeats[s.juror] += 1;
            } else if (i < target) {
                // Non-committing primary: keeps its lock, gamma-slashed later.
                s.status = SeatStatus.Silent;
            } else {
                // Alternate never seated (uncommitted, or panel already full).
                s.status = SeatStatus.Released;
                _jurors[s.juror].lockedSlots -= 1;
            }
        }
        r.seatedCount = seated;
        r.revealEndBlock = uint64(block.number + _config.revealWindowBlocks);
        d.state = DisputeState.Revealing;
        emit PanelSeated(disputeId, d.roundIndex, seated);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // FSM: Revealing — reveal phase + tally
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Reveal the committed vote. Tallies all of the caller's seated seats at
     *         once (weight = seated seat count).
     */
    function revealVote(uint256 disputeId, uint256 choice, bytes32 salt) external {
        Dispute storage d = _getDispute(disputeId);
        if (d.state != DisputeState.Revealing) revert WrongState();
        Round storage r = _rounds[disputeId][d.roundIndex];
        if (block.number > r.revealEndBlock) revert TooLate();
        uint256 seats = r.seatedSeats[msg.sender];
        if (seats == 0) revert NotSeated();
        if (choice == 0 || choice > d.numChoices) revert InvalidChoice();
        if (r.revealedChoice[msg.sender] != 0) revert AlreadyRevealed();
        if (keccak256(abi.encodePacked(disputeId, msg.sender, choice, salt)) != r.commitments[msg.sender]) {
            revert RevealMismatch();
        }
        r.revealedChoice[msg.sender] = choice;
        r.tallyWeight[choice] += seats;
        r.revealedWeight += seats;
        emit VoteRevealed(disputeId, d.roundIndex, msg.sender, choice, seats);
    }

    /**
     * @notice Permissionless crank closing the reveal window.
     * @dev FROZEN quorum: quorumMet iff revealedWeight * BPS >= quorumBps * panelSize
     *      (config panelSize, never seatedCount). Quorum met + unique max-weight
     *      choice => that choice is the final ruling. Quorum met + tie => default
     *      ruling, and at settlement nobody but the silent is slashed. Quorum missed
     *      => this round is finalized HERE (silent gamma-slashed; revealed seats
     *      released and compensated from the pot; NO jurorFee in a failed round) and
     *      the dispute re-arms or terminally applies the default ruling.
     */
    function closeRevealing(uint256 disputeId) external {
        Dispute storage d = _getDispute(disputeId);
        if (d.state != DisputeState.Revealing) revert WrongState();
        Round storage r = _rounds[disputeId][d.roundIndex];
        if (block.number <= r.revealEndBlock) revert TooEarly();

        if (r.revealedWeight * BPS >= uint256(_config.quorumBps) * _config.panelSize) {
            // Quorum met: find the unique max-weight choice or detect a tie.
            uint256 maxW;
            uint256 winner;
            bool tie;
            uint256 nChoices = d.numChoices;
            for (uint256 c = 1; c <= nChoices; ++c) {
                uint256 wgt = r.tallyWeight[c];
                if (wgt > maxW) {
                    maxW = wgt;
                    winner = c;
                    tie = false;
                } else if (wgt != 0 && wgt == maxW) {
                    tie = true;
                }
            }
            if (tie) {
                d.finalRuling = _config.defaultRuling;
                d.terminalKind = TK_TIE;
            } else {
                d.finalRuling = winner;
                d.terminalKind = TK_MAJORITY;
            }
            d.state = DisputeState.Tallied;
            emit RoundTallied(disputeId, d.roundIndex, d.finalRuling, r.revealedWeight);
        } else {
            _finalizeFailedRound(r);
            _failRound(disputeId, d, REASON_NO_QUORUM, TK_QUORUM_FAIL);
        }
    }

    /// @dev Immediate finalization of a quorum-failed round (never revisited):
    ///      SILENT class (never-committed primaries + seated-but-unrevealed) is
    ///      gamma-slashed into pot P'; revealed seats are released unslashed and
    ///      split (BPS - thetaBps) * P' / BPS pro-rata by seat count; theta share
    ///      plus rounding dust is credited to feeSink. No jurorFee here
    ///      (SettlementLib.coherentPayout with jurorFee = 0).
    function _finalizeFailedRound(Round storage r) private {
        uint256 gammaAmt = SettlementLib.slashOf(_config.minStake, _config.gammaBps);
        uint256 len = r.seats.length;

        uint256 silentCount;
        uint256 revealedSeatCount;
        for (uint256 i; i < len; ++i) {
            Seat storage s = r.seats[i];
            if (s.status == SeatStatus.Silent) {
                silentCount += 1;
            } else if (s.status == SeatStatus.Seated) {
                if (r.revealedChoice[s.juror] == 0) silentCount += 1;
                else revealedSeatCount += 1;
            }
        }

        uint256 pot = gammaAmt * silentCount;
        (uint256 perSeat, uint256 dust) =
            SettlementLib.coherentPayout(0, pot, _config.thetaBps, revealedSeatCount);

        for (uint256 i; i < len; ++i) {
            Seat storage s = r.seats[i];
            if (s.status == SeatStatus.Silent) {
                _slashSeat(s.juror, gammaAmt);
            } else if (s.status == SeatStatus.Seated) {
                if (r.revealedChoice[s.juror] == 0) {
                    _slashSeat(s.juror, gammaAmt);
                } else {
                    _jurors[s.juror].lockedSlots -= 1;
                    if (perSeat != 0) _credits[s.juror] += perSeat;
                }
            }
        }

        if (dust != 0) _credits[feeSink] += dust;
    }

    /// @dev Shared re-arm / terminal-default logic for a failed round. Emits
    ///      QuorumFailed on BOTH paths (the round died either way); the terminal
    ///      path additionally emits DefaultRulingApplied.
    function _failRound(uint256 disputeId, Dispute storage d, uint8 reason, uint8 terminalKind) private {
        uint32 closedRound = d.roundIndex;
        d.drawAttempts += 1;
        emit QuorumFailed(disputeId, closedRound, reason);
        if (d.drawAttempts < _config.maxDrawAttempts) {
            d.roundIndex += 1;
            d.drawBlock = uint64(block.number + _config.drawDelayBlocks);
            d.state = DisputeState.Created;
        } else {
            d.finalRuling = _config.defaultRuling;
            d.terminalKind = terminalKind;
            d.state = DisputeState.Tallied;
            emit DefaultRulingApplied(disputeId, d.finalRuling);
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // FSM: Tallied -> Ruled — try/catch delivery + pull re-delivery
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Permissionless crank delivering the ruling to the arbitrable inside
     *         try/catch. Success or recorded failure — the state advances to Ruled
     *         either way: the app can never brick the protocol.
     * @dev The reentrancy lock is held across the callback: rule() implementations
     *      must not call back into state-changing arbitrator functions (they would
     *      revert and the delivery would be recorded failed; redeliverRuling
     *      remains available).
     */
    function deliverRuling(uint256 disputeId) external noReentrant {
        Dispute storage d = _getDispute(disputeId);
        if (d.state != DisputeState.Tallied) revert WrongState();
        d.state = DisputeState.Ruled;
        _attemptDelivery(disputeId, d);
    }

    /// @inheritdoc IArbitrator
    function redeliverRuling(uint256 disputeId) external noReentrant {
        Dispute storage d = _getDispute(disputeId);
        if (d.state != DisputeState.Ruled && d.state != DisputeState.Settled) revert WrongState();
        if (d.delivered) revert AlreadyDelivered();
        _attemptDelivery(disputeId, d);
    }

    function _attemptDelivery(uint256 disputeId, Dispute storage d) private {
        try IArbitrable(d.arbitrable).rule(disputeId, d.finalRuling) {
            d.delivered = true;
            emit Ruling(d.arbitrable, disputeId, d.finalRuling);
        } catch {
            emit RulingDeliveryFailed(d.arbitrable, disputeId, d.finalRuling);
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // FSM: Ruled -> Settled — pull-payment settlement
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Permissionless crank settling the final round and routing fees. Does
     *         NOT require delivery success — a permanently-reverting app cannot block
     *         juror payouts. All payouts are pull-pattern credits (withdraw()).
     * @dev Settles against the snapshotted config semantics: Phase-1 storage config
     *      is immutable, so reading _config IS reading the configHash snapshot.
     *        Case A (unique majority W): coherent seats get jurorFee + an equal floor
     *          share of (BPS-theta)/BPS of pot P = beta*s*|incoherent| +
     *          gamma*s*|silent|; incoherent seats lose beta*s and the fee; silent
     *          seats lose gamma*s and the fee (gamma >= beta by deploy guard: silence
     *          costs more than being wrong).
     *        Case B (terminal tie): only the silent are slashed; every revealed seat
     *          is treated as coherent-class (jurorFee + pot share).
     *        Case C (terminal quorum-fail): the round was already finalized inside
     *          closeRevealing; only fees are routed here.
     *        Case D (terminal draw-short): no seats existed; only fees are routed.
     *      Fee routing: appFeeCut = cost*appFeeBps/BPS to the arbitrable; protocolCut
     *      = cost*protocolFeeBps/BPS to feeSink; jurorFees from the feePool; residue
     *      (forfeited fees) back to the arbitrable; theta pot share + all rounding
     *      dust to feeSink. Never mints: credits <= feePool + slashes.
     */
    function settle(uint256 disputeId) external noReentrant {
        Dispute storage d = _getDispute(disputeId);
        if (d.state != DisputeState.Ruled) revert WrongState();

        uint256 jurorFeesPaid;
        if (d.terminalKind == TK_MAJORITY || d.terminalKind == TK_TIE) {
            jurorFeesPaid = _settleFinalRound(d, _rounds[disputeId][d.roundIndex]);
        }
        // TK_QUORUM_FAIL: round finalized in closeRevealing. TK_DRAW_SHORT: no seats.

        (uint256 appCut, uint256 protocolCut) =
            SettlementLib.feeTakes(_arbCost, _config.appFeeBps, _config.protocolFeeBps);
        // feePool == cost, cost >= appCut + protocolCut + panelSize*jurorFee by the
        // gross-up, and jurorFeesPaid <= seatedCount*jurorFee <= panelSize*jurorFee,
        // so the subtraction cannot underflow.
        uint256 residue = d.feePool - appCut - protocolCut - jurorFeesPaid;

        if (appCut + residue != 0) _credits[d.arbitrable] += appCut + residue;
        if (protocolCut != 0) _credits[feeSink] += protocolCut;

        d.state = DisputeState.Settled;
        emit DisputeSettled(disputeId, d.finalRuling);
    }

    /// @dev Per-seat slash/credit application for a terminal Tallied round
    ///      (majority or tie). Returns the total jurorFee paid out of the feePool.
    function _settleFinalRound(Dispute storage d, Round storage r) private returns (uint256 jurorFeesPaid) {
        uint256 betaAmt = SettlementLib.slashOf(_config.minStake, _config.betaBps);
        uint256 gammaAmt = SettlementLib.slashOf(_config.minStake, _config.gammaBps);
        bool tieCase = d.terminalKind == TK_TIE;
        uint256 winner = d.finalRuling;
        uint256 len = r.seats.length;

        // Pass 1: classify.
        uint256 coherentCount;
        uint256 incoherentCount;
        uint256 silentCount;
        for (uint256 i; i < len; ++i) {
            Seat storage s = r.seats[i];
            if (s.status == SeatStatus.Silent) {
                silentCount += 1;
            } else if (s.status == SeatStatus.Seated) {
                uint256 ch = r.revealedChoice[s.juror];
                if (ch == 0) silentCount += 1;
                else if (tieCase || ch == winner) coherentCount += 1;
                else incoherentCount += 1;
            }
        }

        uint256 pot = SettlementLib.potOf(
            _config.minStake, _config.betaBps, _config.gammaBps, incoherentCount, silentCount
        );
        (uint256 perSeat, uint256 dust) =
            SettlementLib.coherentPayout(_config.jurorFee, pot, _config.thetaBps, coherentCount);
        uint256 fee = _config.jurorFee;

        // Pass 2: apply.
        for (uint256 i; i < len; ++i) {
            Seat storage s = r.seats[i];
            if (s.status == SeatStatus.Silent) {
                _slashSeat(s.juror, gammaAmt);
            } else if (s.status == SeatStatus.Seated) {
                uint256 ch = r.revealedChoice[s.juror];
                if (ch == 0) {
                    _slashSeat(s.juror, gammaAmt);
                } else if (tieCase || ch == winner) {
                    _jurors[s.juror].lockedSlots -= 1;
                    _credits[s.juror] += perSeat; // == fee + pot share
                    jurorFeesPaid += fee;
                } else {
                    _slashSeat(s.juror, betaAmt);
                }
            }
        }

        if (dust != 0) _credits[feeSink] += dust; // theta share + rounding dust
    }

    /// @dev Slashes one seat: reduces the juror's escrowed stake by amount, releases
    ///      the slot lock, and shrinks the global stake accumulator. amount <=
    ///      minStake (gamma <= BPS), and every locked slot is minStake-backed, so
    ///      this never underflows and never takes more than the locked slot stake.
    function _slashSeat(address juror, uint256 amount) private {
        Juror storage j = _jurors[juror];
        j.stakedAmount -= amount;
        j.lockedSlots -= 1;
        totalStaked -= amount;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Pull payments
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice Withdraw all accumulated credits (juror payouts, app fee residues +
    ///         createDispute overpayments, feeSink cuts). Credit is zeroed before the
    ///         transfer; a failed transfer reverts the whole call, restoring the credit.
    function withdraw() external noReentrant {
        uint256 amount = _credits[msg.sender];
        if (amount == 0) revert NothingToWithdraw();
        _credits[msg.sender] = 0;
        emit Withdrawn(msg.sender, amount);
        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        if (!ok) revert TransferFailed();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Views
    // ─────────────────────────────────────────────────────────────────────────

    /// @inheritdoc IArbitrator
    function disputeStatus(uint256 disputeId) external view returns (uint8 state, uint256 ruling, bool delivered) {
        Dispute storage d = _disputes[disputeId];
        return (uint8(d.state), d.finalRuling, d.delivered);
    }

    /// @notice The full (immutable) Phase-1 court config.
    function courtConfig() external view returns (CourtConfig memory) {
        return _config;
    }

    /// @notice keccak256(abi.encode(courtConfig())) — snapshotted into every dispute.
    function configHash() external view returns (bytes32) {
        return _configHash;
    }

    /// @notice Juror escrow snapshot: staked balance, locked slots, activation block.
    function jurorInfo(address juror)
        external
        view
        returns (uint256 stakedAmount, uint256 lockedSlots, uint64 activatesAtBlock)
    {
        Juror storage j = _jurors[juror];
        return (j.stakedAmount, j.lockedSlots, j.activatesAtBlock);
    }

    /// @notice Pull-payment credit currently withdrawable by `account`.
    function withdrawable(address account) external view returns (uint256) {
        return _credits[account];
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Internal helpers
    // ─────────────────────────────────────────────────────────────────────────

    function _getDispute(uint256 disputeId) private view returns (Dispute storage d) {
        d = _disputes[disputeId];
        if (d.state == DisputeState.None) revert DisputeNotFound();
    }

    function _ceilDiv(uint256 a, uint256 b) private pure returns (uint256) {
        return a == 0 ? 0 : (a - 1) / b + 1;
    }
}

