pragma solidity ^0.8.28;

import {IEligibility} from "../interfaces/IEligibility.sol";

/**
 * @title IZKPassportRegistry
 * @notice Minimal read-only view of the already-deployed same-chain ZKPassport
 *         proof-of-personhood registry. Declared inline on purpose: this policy
 *         depends only on the one function it consumes, never on the registry's
 *         full ABI.
 * @dev The registry maintains a bytes32 uniqueId => wallet binding under the hood,
 *      so one verified passport maps to exactly one wallet address.
 */
interface IZKPassportRegistry {
    /**
     * @notice Whether `wallet` currently holds a valid ZKPassport verification.
     * @param wallet The address to check.
     */
    function isVerified(address wallet) external view returns (bool);
}

/// @notice Constructor guard: the ZKPassportRegistry address may not be zero.
error ZeroRegistry();

/**
 * @title PopGatedEligibility
 * @notice Phase-1 proof-of-personhood juror-eligibility policy: a juror may claim
 *         seats iff their wallet is verified in the ZKPassportRegistry. Combined
 *         with the registry's one-passport-one-wallet uniqueId binding, this yields
 *         sybil-resistant panels — one verified human = one juror identity —
 *         which is the differentiator of the PoP-gated court.
 * @dev Implements the FROZEN IEligibility seam consumed by ArbitratorCore at
 *      seat-claim time. Stake requirements live in the core; only identity gating
 *      lives here.
 *
 *      Statelessness: this contract holds no storage beyond one immutable, has no
 *      owner, no admin, and no value-transfer paths (hence no noReentrant guard is
 *      needed — there is nothing to guard). The registry address is fixed forever
 *      at deploy; pointing the court at a different registry means deploying a new
 *      policy and a new court.
 *
 *      Failure containment: the core invokes isEligible inside a try/catch. If the
 *      underlying registry ever reverts or misbehaves, this call reverts with it
 *      and the core treats the juror as ineligible for that claim — a broken
 *      registry can block seat claims but can never brick a dispute (quorum-fail
 *      re-draws and the default ruling still terminate it).
 */
contract PopGatedEligibility is IEligibility {
    /// @dev The already-deployed same-chain ZKPassportRegistry this policy wraps.
    IZKPassportRegistry private immutable _registry;

    /**
     * @notice Deploys the policy bound permanently to one ZKPassportRegistry.
     * @param zkPassportRegistry Address of the deployed ZKPassportRegistry.
     * @dev Reverts with ZeroRegistry if the address is zero. Emits no event:
     *      the immutable binding is fully visible in the deploy transaction and
     *      via registry(); there is no mutable state to journal.
     */
    constructor(address zkPassportRegistry) {
        if (zkPassportRegistry == address(0)) revert ZeroRegistry();
        _registry = IZKPassportRegistry(zkPassportRegistry);
    }

    /**
     * @notice Whether `juror` may claim seats in this court right now.
     * @param juror The staked wallet attempting a seat claim.
     * @return True iff the juror's wallet holds a valid ZKPassport verification.
     * @dev Pure pass-through to ZKPassportRegistry.isVerified. A revert in the
     *      registry propagates and is absorbed by the core's try/catch, rendering
     *      the juror ineligible for that claim without affecting dispute liveness.
     */
    function isEligible(address juror) external view override returns (bool) {
        return _registry.isVerified(juror);
    }

    /**
     * @notice The ZKPassportRegistry this policy is permanently bound to.
     * @return The registry contract address.
     */
    function registry() external view returns (address) {
        return address(_registry);
    }
}

