import {IEligibility} from "../interfaces/IEligibility.sol";

/**
 * @title StakeWeightedEligibility
 * @notice Phase-1 stake-only eligibility policy: every juror is eligible.
 * @dev One of the two live IEligibility policies shipped with the Phase-1 court
 *      (the other being PopGatedEligibility). For courts where juror gating is
 *      purely economic, all real gating already lives in ArbitratorCore:
 *        - stake escrow and per-slot weight (stakedAmount / minStake);
 *        - activation delay (anti just-in-time staking);
 *        - VRF seat-claim admission below tau with lowest-output ranking.
 *      This policy therefore holds zero state, takes zero constructor args, and
 *      unconditionally returns true. It exists so the IEligibility seam has two
 *      concrete implementations from day one and a PoP-gated court can be swapped
 *      for a stake-only court (or vice versa) without touching the core.
 *
 *      The core calls isEligible inside try/catch, so even a hostile or broken
 *      policy can only block seat claims, never brick a dispute; this
 *      implementation cannot revert at all.
 *
 *      No state changes occur here, so no events are emitted; no value is
 *      transferred, so no reentrancy guard is needed.
 */
contract StakeWeightedEligibility is IEligibility {
    /**
     * @notice Whether `juror` may claim seats in this court right now.
     * @dev Always true — economic gating (stake, activation delay, tau) is
     *      enforced by the core, not by this policy. Declared pure, which is a
     *      valid restriction of the interface's view mutability.
     * @return eligible Always true for every address.
     */
    function isEligible(address /* juror */) external pure returns (bool eligible) {
        return true;
    }
}

