pragma solidity ^0.8.28;

import {IArbitrable} from "../interfaces/IArbitrable.sol";
import {IArbitrator} from "../interfaces/IArbitrator.sol";
import {
    ReentrancyGuard,
    TransferFailed,
    NothingToWithdraw,
    FeeTooLow,
    ZeroAmount
} from "../lib/Errors.sol";

/**
 * @title IArbitratorCreditPull
 * @notice Minimal local seam for pulling this app's withdrawable credit out of
 *         ArbitratorCore. Not part of the frozen IArbitrator interface: the
 *         frozen seam only covers dispute creation/status/redelivery, while the
 *         credit ledger (app-fee cut + fee residue assigned to the arbitrable at
 *         settlement, plus createDispute overpayments) is pulled via the core's
 *         own `withdraw()`.
 */
interface IArbitratorCreditPull {
    function withdraw() external;
}

/**
 * @title SimpleEscrow
 * @notice Minimal IArbitrable reference app proving the Phase-1 arbitration seam
 *         end-to-end. Two-party native (PAS) escrow:
 *           - the payer creates an agreement escrowing msg.value for a payee;
 *           - either party may end it cooperatively (payer `release`s to the
 *             payee, payee `refund`s to the payer);
 *           - either party may instead open a dispute by paying
 *             IArbitrator.arbitrationCost and the arbitrator later pushes the
 *             ruling back via `rule()`.
 *         Ruling convention (binary dispute, numChoices = 2):
 *           1 = refund the payer, 2 = release to the payee,
 *           0 (refused/default) = 50/50 split, dust (1 wei on odd amounts) to
 *           the payer. Any other value is treated defensively as 0.
 * @dev Everything pays out through a pull-pattern withdrawable-credit ledger
 *      (`credits`) guarded by a custom noReentrant modifier — the only native
 *      transfers out are in `withdraw()`. `rule()` is idempotent: duplicate or
 *      unknown deliveries return silently so a retried delivery can never
 *      double-spend the escrow or revert the arbitrator's try/catch path.
 *
 *      MVP simplification (documented, accepted): the app-fee cut and fee
 *      residue the arbitrator credits to this contract at settlement are an
 *      unattributable aggregate across all disputes (the core's `withdraw()`
 *      pulls one lump sum). `claimArbitratorCredit()` therefore sweeps the
 *      pulled amount to its caller as a permissionless keeper incentive.
 *      A production app would attribute credits per dispute; `openDispute`
 *      minimises what flows through this path by forwarding exactly
 *      `arbitrationCost` and crediting any overpayment back to the opener
 *      locally.
 */
contract SimpleEscrow is IArbitrable {
    // ─────────────────────────────────────────────────────────────────────────
    // Errors (shared runtime errors imported from lib/Errors.sol)
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice rule() caller is not the configured arbitrator.
    error NotArbitrator();
    /// @notice Constructor got address(0) for the arbitrator.
    error ZeroArbitrator();
    /// @notice createAgreement with payee == address(0).
    error ZeroPayee();
    /// @notice Agreement is not in the state this action requires.
    error AgreementNotActive();
    /// @notice Caller is neither the payer nor the payee of the agreement.
    error NotParty();
    /// @notice release() caller is not the agreement's payer.
    error NotPayer();
    /// @notice refund() caller is not the agreement's payee.
    error NotPayee();
    /// @notice Plain native transfer into this contract from anyone but the
    ///         arbitrator (escrow funding must go through createAgreement).
    error DirectDepositRejected();

    // ─────────────────────────────────────────────────────────────────────────
    // Events (RulingExecuted is inherited from IArbitrable)
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice A new escrow agreement was funded.
    event AgreementCreated(uint256 indexed agreementId, address indexed payer, address indexed payee, uint256 amount);

    /// @notice The payer cooperatively released the escrow to the payee.
    event AgreementReleased(uint256 indexed agreementId, address indexed payee, uint256 amount);

    /// @notice The payee cooperatively refunded the escrow to the payer.
    event AgreementRefunded(uint256 indexed agreementId, address indexed payer, uint256 amount);

    /// @notice A party escalated the agreement to the arbitrator.
    event DisputeOpened(uint256 indexed agreementId, uint256 indexed disputeId, address indexed opener, uint256 cost);

    /// @notice Aggregate arbitrator credit was pulled and swept to the caller.
    event ArbitratorCreditClaimed(address indexed caller, uint256 amount);

    /// @notice An account pulled its withdrawable credit.
    event Withdrawn(address indexed account, uint256 amount);

    // ─────────────────────────────────────────────────────────────────────────
    // Types + storage
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice Agreement lifecycle. Resolved is terminal (funds live on in `credits`).
    enum AgreementStatus {
        None,     // 0 - does not exist
        Active,   // 1 - escrowed; cooperative release/refund or dispute possible
        Disputed, // 2 - escalated; waiting for rule()
        Resolved  // 3 - terminal; escrow apportioned into credits
    }

    struct Agreement {
        address payer;          // funded the escrow; ruling 1 refunds them
        address payee;          // beneficiary; ruling 2 releases to them
        uint256 amount;         // escrowed native amount (PAS wei)
        AgreementStatus status; // lifecycle state
        uint256 disputeId;      // arbitrator dispute id once Disputed; 0 before
    }

    /// @notice Binary dispute: 1 = refund payer, 2 = release payee.
    uint8 private constant NUM_CHOICES = 2;
    uint256 private constant RULING_REFUND_PAYER = 1;
    uint256 private constant RULING_RELEASE_PAYEE = 2;

    /// @notice The one trusted arbitrator this app consumes rulings from.
    IArbitrator public immutable arbitrator;

    /// @notice Monotonic agreement id counter; ids start at 1 (0 is the null agreement).
    uint256 public agreementCount;

    /// @notice agreementId => agreement.
    mapping(uint256 => Agreement) public agreements;

    /// @notice arbitrator disputeId => agreementId (0 = unknown dispute).
    mapping(uint256 => uint256) public disputeToAgreement;

    /// @notice Pull-pattern withdrawable native credit per account.
    mapping(address => uint256) public credits;

    /// @dev Custom reentrancy latch (p2p-market style, not OZ). 1 = free, 2 = entered.
    uint256 private _entered = 1;

    /// @dev Guards every path that moves native value out of, or into and back
    ///      out of, this contract within one call.
    modifier noReentrant() {
        if (_entered == 2) revert ReentrancyGuard();
        _entered = 2;
        _;
        _entered = 1;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Setup
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @param arbitrator_ The deployed ArbitratorCore this app trusts. Immutable:
     *        this reference app has no owner, no admin and no way to re-point.
     */
    constructor(address arbitrator_) {
        if (arbitrator_ == address(0)) revert ZeroArbitrator();
        arbitrator = IArbitrator(arbitrator_);
    }

    /**
     * @notice Accepts native value only from the arbitrator (its `withdraw()`
     *         pushes this app's settlement credits here via .call{value:}).
     *         Everyone else must fund escrow through createAgreement.
     */
    receive() external payable {
        if (msg.sender != address(arbitrator)) revert DirectDepositRejected();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Escrow lifecycle
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Fund a new escrow agreement. msg.sender is the payer; msg.value is
     *         escrowed until release, refund, or a delivered ruling.
     * @param payee The counterparty a ruling of 2 (or a cooperative release) pays.
     * @return agreementId Monotonic id, starting at 1.
     */
    function createAgreement(address payee) external payable returns (uint256 agreementId) {
        if (payee == address(0)) revert ZeroPayee();
        if (msg.value == 0) revert ZeroAmount();

        agreementId = ++agreementCount;
        agreements[agreementId] = Agreement({
            payer: msg.sender,
            payee: payee,
            amount: msg.value,
            status: AgreementStatus.Active,
            disputeId: 0
        });

        emit AgreementCreated(agreementId, msg.sender, payee, msg.value);
    }

    /**
     * @notice Cooperative happy path: the payer releases the full escrow to the
     *         payee. Only callable while Active (not once disputed).
     */
    function release(uint256 agreementId) external {
        Agreement storage a = agreements[agreementId];
        if (a.status != AgreementStatus.Active) revert AgreementNotActive();
        if (msg.sender != a.payer) revert NotPayer();

        a.status = AgreementStatus.Resolved;
        credits[a.payee] += a.amount;

        emit AgreementReleased(agreementId, a.payee, a.amount);
    }

    /**
     * @notice Cooperative unwind: the payee refunds the full escrow to the
     *         payer. Only callable while Active (not once disputed).
     */
    function refund(uint256 agreementId) external {
        Agreement storage a = agreements[agreementId];
        if (a.status != AgreementStatus.Active) revert AgreementNotActive();
        if (msg.sender != a.payee) revert NotPayee();

        a.status = AgreementStatus.Resolved;
        credits[a.payer] += a.amount;

        emit AgreementRefunded(agreementId, a.payer, a.amount);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Arbitration seam
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Escalate an Active agreement to the arbitrator. Either party pays
     *         the arbitration fee; exactly `arbitrationCost` is forwarded and
     *         any overpayment is credited back to the opener here (pull).
     * @dev The escrowed amount stays put; only its eventual destination is now
     *      up to the ruling. There is no timeout path back to Active — once
     *      Disputed, the agreement resolves solely via rule(), which the
     *      arbitrator's FSM guarantees will eventually arrive (or be
     *      redeliverable) for every dispute.
     * @param agreementId The Active agreement to dispute.
     * @return disputeId The arbitrator's dispute id, mapped for rule().
     */
    function openDispute(uint256 agreementId) external payable noReentrant returns (uint256 disputeId) {
        Agreement storage a = agreements[agreementId];
        if (a.status != AgreementStatus.Active) revert AgreementNotActive();
        if (msg.sender != a.payer && msg.sender != a.payee) revert NotParty();

        bytes memory extraData = abi.encode(agreementId);
        uint256 cost = arbitrator.arbitrationCost(extraData);
        if (msg.value < cost) revert FeeTooLow();

        a.status = AgreementStatus.Disputed;

        disputeId = arbitrator.createDispute{value: cost}(NUM_CHOICES, extraData);
        a.disputeId = disputeId;
        disputeToAgreement[disputeId] = agreementId;

        if (msg.value > cost) {
            credits[msg.sender] += msg.value - cost;
        }

        emit DisputeOpened(agreementId, disputeId, msg.sender, cost);
    }

    /**
     * @notice Ruling delivery from the arbitrator (called inside its try/catch).
     * @dev Idempotent by design: an unknown disputeId or an already-Resolved
     *      agreement returns silently instead of reverting, so a redelivery can
     *      never double-apportion the escrow and a revert here never costs the
     *      protocol anything (it would only mark delivery failed). Apportioning:
     *        1 = full refund to payer; 2 = full release to payee;
     *        0 / anything else = 50/50 split, dust to the payer.
     * @param disputeId Id returned by createDispute.
     * @param ruling 0 = refused/default; 1..2 = app choices.
     */
    function rule(uint256 disputeId, uint256 ruling) external {
        if (msg.sender != address(arbitrator)) revert NotArbitrator();

        uint256 agreementId = disputeToAgreement[disputeId];
        if (agreementId == 0) return; // not a dispute this app opened; ignore

        Agreement storage a = agreements[agreementId];
        if (a.status != AgreementStatus.Disputed) return; // duplicate delivery; idempotent

        a.status = AgreementStatus.Resolved;
        uint256 amount = a.amount;

        if (ruling == RULING_REFUND_PAYER) {
            credits[a.payer] += amount;
        } else if (ruling == RULING_RELEASE_PAYEE) {
            credits[a.payee] += amount;
        } else {
            // 0 = refused/default, or defensively any out-of-range value.
            uint256 half = amount / 2;
            credits[a.payee] += half;
            credits[a.payer] += amount - half; // dust (1 wei on odd amounts) to payer
        }

        emit RulingExecuted(msg.sender, disputeId, ruling);
    }

    /**
     * @notice Pull this app's aggregate withdrawable credit out of the
     *         arbitrator (app-fee cuts + fee residue assigned at settlement)
     *         and sweep it to the caller.
     * @dev Permissionless keeper sweep — see the contract-level MVP note: the
     *      arbitrator's credit ledger is one lump sum per beneficiary, so
     *      per-dispute attribution is impossible from here. Reverts (bubbling
     *      the arbitrator's NothingToWithdraw) when there is nothing to pull.
     *      The arbitrator pushes the value into receive() during this call;
     *      the caller then exits via withdraw() like everyone else.
     */
    function claimArbitratorCredit() external noReentrant {
        uint256 balanceBefore = address(this).balance;
        IArbitratorCreditPull(address(arbitrator)).withdraw();
        uint256 pulled = address(this).balance - balanceBefore;
        if (pulled == 0) revert NothingToWithdraw();

        credits[msg.sender] += pulled;

        emit ArbitratorCreditClaimed(msg.sender, pulled);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Withdrawals
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Pull-pattern exit for every credit this contract assigns: escrow
     *         apportionments, dispute-fee overpayment refunds, and swept
     *         arbitrator credits.
     * @dev Zeroes the credit BEFORE the native transfer; a failed transfer
     *      reverts, restoring the credit via revert semantics.
     */
    function withdraw() external noReentrant {
        uint256 amount = credits[msg.sender];
        if (amount == 0) revert NothingToWithdraw();

        credits[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: amount}("");
        if (!ok) revert TransferFailed();

        emit Withdrawn(msg.sender, amount);
    }
}

